/**
 * floatrepr.mjs
 *
 * Faithful re-implementation of CPython's `float.__repr__` / `float.__str__`
 * output format (`PyOS_double_to_string` with format code 'r').
 *
 * CPython produces the *shortest* decimal string that round-trips back to the
 * same double (David Gay / Grisu style "mode 0" conversion), then decides
 * between fixed and exponential notation using the decimal exponent:
 *
 *     use_exponent  <==>  decpt <= -4  ||  decpt > 16
 *
 * where `decpt` is positioned such that the value equals
 * `0.<digits> * 10**decpt`.
 *
 * JavaScript's `Number.prototype.toString()` also emits the shortest
 * round-tripping representation, but switches to exponential notation at
 * different thresholds (1e21 and 1e-7).  So we harvest the shortest digit
 * string from JS and re-assemble it with CPython's layout rules.
 */

/**
 * Decompose a finite, non-negative double into its shortest round-tripping
 * decimal digit string plus CPython's `decpt`.
 *
 * @param {number} a - finite, >= 0
 * @returns {{digits: string, decpt: number}}
 */
export function shortestDigits(a) {
  const s = String(a);

  let digits;
  let decpt;

  const ePos = s.indexOf('e');
  if (ePos !== -1) {
    const mant = s.slice(0, ePos);
    const exp = parseInt(s.slice(ePos + 1), 10);
    const dot = mant.indexOf('.');
    if (dot === -1) {
      digits = mant;
      decpt = mant.length + exp;
    } else {
      digits = mant.slice(0, dot) + mant.slice(dot + 1);
      decpt = dot + exp;
    }
  } else {
    const dot = s.indexOf('.');
    if (dot === -1) {
      digits = s;
      decpt = s.length;
    } else {
      digits = s.slice(0, dot) + s.slice(dot + 1);
      decpt = dot;
    }
  }

  // Normalise: drop leading zeros (each one shifts the decimal point left).
  let lead = 0;
  while (lead < digits.length - 1 && digits[lead] === '0') {
    lead += 1;
    decpt -= 1;
  }
  digits = digits.slice(lead);

  // Drop trailing zeros; they carry no information in "shortest" form.
  let end = digits.length;
  while (end > 1 && digits[end - 1] === '0') end -= 1;
  digits = digits.slice(0, end);

  if (digits === '' || digits === '0') {
    digits = '0';
    decpt = 1;
  }

  return { digits, decpt };
}

/** Format CPython's two-or-more-digit signed exponent, e.g. `e+16`, `e-07`. */
function formatExponent(exp) {
  const sign = exp < 0 ? '-' : '+';
  let mag = String(Math.abs(exp));
  if (mag.length < 2) mag = '0' + mag;
  return 'e' + sign + mag;
}

/**
 * Core formatter.
 *
 * @param {number} x
 * @param {boolean} addDotZero - when true (repr/str of a float) an integral
 *   value rendered in fixed notation gets a trailing `.0`, matching
 *   `Py_DTSF_ADD_DOT_0`.  `complex.__repr__` formats its parts *without* the
 *   flag, which is why `repr(3+4j)` is `(3+4j)` and not `(3.0+4.0j)`.
 */
export function formatDouble(x, addDotZero) {
  if (Number.isNaN(x)) return 'nan';
  if (x === Infinity) return 'inf';
  if (x === -Infinity) return '-inf';

  // Object.is catches -0.0, whose sign CPython also preserves.
  const negative = x < 0 || Object.is(x, -0);
  const a = Math.abs(x);

  const { digits, decpt } = shortestDigits(a);
  const useExponent = decpt <= -4 || decpt > 16;

  let body;
  if (useExponent) {
    body = digits[0];
    if (digits.length > 1) body += '.' + digits.slice(1);
    body += formatExponent(decpt - 1);
  } else if (decpt <= 0) {
    body = '0.' + '0'.repeat(-decpt) + digits;
  } else if (decpt >= digits.length) {
    body = digits + '0'.repeat(decpt - digits.length);
    if (addDotZero) body += '.0';
  } else {
    body = digits.slice(0, decpt) + '.' + digits.slice(decpt);
  }

  return negative ? '-' + body : body;
}

/** `repr(x)` / `str(x)` for a Python float. */
export function floatRepr(x) {
  return formatDouble(x, true);
}

/** Float formatting used by `complex.__repr__` (no `.0` padding). */
export function floatReprBare(x) {
  return formatDouble(x, false);
}

