/**
 * pyvalues.mjs
 *
 * The Python value model.  Every Python object produced by the expression
 * evaluator is a tagged plain object (or, for the container types that need
 * behaviour, a small class living in its own module).  Keeping the tag as a
 * bare string means the low-level helpers here have no imports at all, which
 * keeps the module graph acyclic.
 *
 * The tag doubles as `type(x).__name__`, which the source program prints.
 */

// ---------------------------------------------------------------------------
// Type tags
// ---------------------------------------------------------------------------

export const T_NONE = 'NoneType';
export const T_BOOL = 'bool';
export const T_INT = 'int';
export const T_FLOAT = 'float';
export const T_COMPLEX = 'complex';
export const T_STR = 'str';
export const T_BYTES = 'bytes';
export const T_LIST = 'list';
export const T_TUPLE = 'tuple';
export const T_SET = 'set';
export const T_FROZENSET = 'frozenset';
export const T_DICT = 'dict';
export const T_RANGE = 'range';
export const T_SLICE = 'slice';
export const T_FUNCTION = 'function';
export const T_BUILTIN = 'builtin_function_or_method';
export const T_TYPE = 'type';
export const T_METHOD = 'builtin_function_or_method';
export const T_DICT_KEYS = 'dict_keys';
export const T_DICT_VALUES = 'dict_values';
export const T_DICT_ITEMS = 'dict_items';
export const T_GENERATOR = 'generator';

/** Lazy iterator-like builtins keep their own type names, as CPython does. */
export const LAZY_TAGS = new Set([
  T_GENERATOR,
  'map',
  'filter',
  'zip',
  'enumerate',
  'reversed',
  'list_iterator',
  'str_iterator',
  'tuple_iterator',
  'set_iterator',
  'dict_keyiterator',
  'range_iterator',
]);

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

/** A raised Python exception, carrying the class name CPython would print. */
export class PyError extends Error {
  constructor(kind, message) {
    super(message === undefined ? kind : `${kind}: ${message}`);
    this.kind = kind;
    this.pyMessage = message === undefined ? '' : message;
  }
}

export const typeError = (m) => new PyError('TypeError', m);
export const valueError = (m) => new PyError('ValueError', m);
export const keyError = (m) => new PyError('KeyError', m);
export const indexError = (m) => new PyError('IndexError', m);
export const nameError = (m) => new PyError('NameError', m);
export const attributeError = (m) => new PyError('AttributeError', m);
export const zeroDivisionError = (m) => new PyError('ZeroDivisionError', m);
export const syntaxError = (m) => new PyError('SyntaxError', m);
export const overflowError = (m) => new PyError('OverflowError', m);
export const stopIteration = () => new PyError('StopIteration', undefined);

// ---------------------------------------------------------------------------
// Constructors / singletons
// ---------------------------------------------------------------------------

export const NONE = Object.freeze({ t: T_NONE });
export const TRUE = Object.freeze({ t: T_BOOL, v: true });
export const FALSE = Object.freeze({ t: T_BOOL, v: false });

export const mkBool = (b) => (b ? TRUE : FALSE);
export const mkInt = (v) => ({ t: T_INT, v: typeof v === 'bigint' ? v : BigInt(v) });
export const mkFloat = (v) => ({ t: T_FLOAT, v: Number(v) });
export const mkComplex = (re, im) => ({ t: T_COMPLEX, re: Number(re), im: Number(im) });
export const mkStr = (v) => ({ t: T_STR, v: String(v) });
export const mkBytes = (v) => ({ t: T_BYTES, v: v instanceof Uint8Array ? v : new Uint8Array(v) });
export const mkList = (items) => ({ t: T_LIST, v: items });
export const mkTuple = (items) => ({ t: T_TUPLE, v: items });
export const mkRange = (start, stop, step) => ({
  t: T_RANGE,
  start: BigInt(start),
  stop: BigInt(stop),
  step: BigInt(step),
});
export const mkSlice = (start, stop, step) => ({ t: T_SLICE, start, stop, step });

/** Wrap a JS iterator as a one-shot Python iterator/generator object. */
export const mkLazy = (tag, iterator) => ({ t: tag, it: iterator });

export const mkView = (tag, dict) => ({ t: tag, d: dict });

// ---------------------------------------------------------------------------
// Predicates
// ---------------------------------------------------------------------------

export const typeName = (v) => v.t;

export const isInt = (v) => v.t === T_INT;
export const isBool = (v) => v.t === T_BOOL;
export const isFloat = (v) => v.t === T_FLOAT;
export const isStr = (v) => v.t === T_STR;
export const isBytes = (v) => v.t === T_BYTES;
export const isNone = (v) => v.t === T_NONE;

/** `isinstance(x, int)` — note that in Python `bool` is a subclass of `int`. */
export const isIntLike = (v) => v.t === T_INT || v.t === T_BOOL;

/** True for anything `isinstance(x, (int, float))` accepts (bool included). */
export const isIntOrFloat = (v) => v.t === T_INT || v.t === T_BOOL || v.t === T_FLOAT;

const ITERABLE_TAGS = new Set([
  T_STR,
  T_BYTES,
  T_LIST,
  T_TUPLE,
  T_SET,
  T_FROZENSET,
  T_DICT,
  T_RANGE,
  T_DICT_KEYS,
  T_DICT_VALUES,
  T_DICT_ITEMS,
]);

/**
 * `isinstance(x, collections.abc.Iterable)` — i.e. "does it define __iter__".
 * boltons leans on exactly this check.
 */
export function isIterable(v) {
  return ITERABLE_TAGS.has(v.t) || LAZY_TAGS.has(v.t);
}

/**
 * boltons.iterutils treats `str` and `bytes` as atoms even though they *are*
 * iterable, so `flatten` never explodes a string into characters.
 */
export function isStringish(v) {
  return v.t === T_STR || v.t === T_BYTES;
}

// ---------------------------------------------------------------------------
// Iteration
// ---------------------------------------------------------------------------

/** Split a JS string into Python-style codepoint characters. */
export const strChars = (s) => Array.from(s);

function* rangeIter(r) {
  const { start, stop, step } = r;
  if (step === 0n) throw valueError('range() arg 3 must not be zero');
  if (step > 0n) for (let i = start; i < stop; i += step) yield mkInt(i);
  else for (let i = start; i > stop; i += step) yield mkInt(i);
}

/**
 * Return a JS iterable of Python values for any iterable Python object.
 * Lazy objects are consumed, exactly as in Python.
 */
export function iterValues(v) {
  switch (v.t) {
    case T_STR:
      return strChars(v.v).map(mkStr);
    case T_BYTES:
      return Array.from(v.v, (b) => mkInt(BigInt(b)));
    case T_LIST:
    case T_TUPLE:
      return v.v;
    case T_RANGE:
      return rangeIter(v);
    case T_SET:
    case T_FROZENSET:
      return v.items();
    case T_DICT:
      return v.keys();
    case T_DICT_KEYS:
      return v.d.keys();
    case T_DICT_VALUES:
      return v.d.values();
    case T_DICT_ITEMS:
      return v.d.items().map(([k, val]) => mkTuple([k, val]));
    default:
      if (LAZY_TAGS.has(v.t)) return { [Symbol.iterator]: () => v.it };
      throw typeError(`'${v.t}' object is not iterable`);
  }
}

/** Materialise any iterable into a JS array of Python values. */
export function toArray(v) {
  const out = [];
  for (const item of iterValues(v)) out.push(item);
  return out;
}

// ---------------------------------------------------------------------------
// Truthiness / length
// ---------------------------------------------------------------------------

export function truthy(v) {
  switch (v.t) {
    case T_NONE:
      return false;
    case T_BOOL:
      return v.v;
    case T_INT:
      return v.v !== 0n;
    case T_FLOAT:
      return v.v !== 0;
    case T_COMPLEX:
      return v.re !== 0 || v.im !== 0;
    case T_STR:
      return v.v.length > 0;
    case T_BYTES:
      return v.v.length > 0;
    case T_LIST:
    case T_TUPLE:
      return v.v.length > 0;
    case T_SET:
    case T_FROZENSET:
      return v.size > 0;
    case T_DICT:
      return v.size > 0;
    case T_RANGE:
      return pyLen(v) > 0;
    case T_DICT_KEYS:
    case T_DICT_VALUES:
    case T_DICT_ITEMS:
      return v.d.size > 0;
    default:
      return true;
  }
}

export function pyLen(v) {
  switch (v.t) {
    case T_STR:
      return strChars(v.v).length;
    case T_BYTES:
      return v.v.length;
    case T_LIST:
    case T_TUPLE:
      return v.v.length;
    case T_SET:
    case T_FROZENSET:
      return v.size;
    case T_DICT:
      return v.size;
    case T_DICT_KEYS:
    case T_DICT_VALUES:
    case T_DICT_ITEMS:
      return v.d.size;
    case T_RANGE: {
      const { start, stop, step } = v;
      if (step > 0n) return stop > start ? Number((stop - start - 1n) / step) + 1 : 0;
      return stop < start ? Number((start - stop - 1n) / -step) + 1 : 0;
    }
    default:
      throw typeError(`object of type '${v.t}' has no len()`);
  }
}

