const BITS = 61n;
const INF_HASH = 314159n;

/** `hash(int)` for an arbitrary-precision integer. */
export function hashBigInt(n) {
  const negative = n < 0n;
  let h = (negative ? -n : n) % MODULUS;
  if (negative) h = -h;
  if (h === -1n) h = -2n;
  return h;
