    if (Number.isNaN(x)) return 0n; // matches CPython < 3.10; NaN in a set is a corner case
    return x > 0 ? INF_HASH : -INF_HASH;
  }
  if (Number.isInteger(x) && Math.abs(x) < 9007199254740992) {
    return hashBigInt(BigInt(x));
