/**
 * pyset.mjs
 *
 * `set` / `frozenset` with CPython's *iteration order* reproduced.
 *
 * Set order is observable here: the source program flattens dict values, so a
 * set inside the input literal dictates the order of everything downstream.
 * CPython's order is simply "ascending hash-table slot", so we model the real
 * table: open addressing with 9 linear probes followed by the
 * `i = i*5 + 1 + perturb` recurrence, plus the growth policy.
 *
 * This is only reproducible for elements whose hash is deterministic (ints,
 * bools, floats).  `str`, `bytes` and `None` hashes vary per process in
 * CPython, so for those we fall back to insertion order and accept that the
 * order is unknowable rather than guess wrong deterministically.
 */

import { T_FROZENSET, T_SET } from './pyvalues.mjs';
import { hashKey, pyHash } from './pyhash.mjs';

const MASK64 = (1n << 64n) - 1n;
const LINEAR_PROBES = 9n;
const PERTURB_SHIFT = 5n;
const MIN_SIZE = 8;

const u64 = (x) => x & MASK64;

/** CPython's `set_insert_clean`, used when rehashing into a bigger table. */
function insertClean(table, mask, entry) {
  let perturb = u64(entry.hash);
  let i = u64(entry.hash) & mask;
  for (;;) {
    if (table[Number(i)] === undefined) {
      table[Number(i)] = entry;
      return;
    }
    if (i + LINEAR_PROBES <= mask) {
      for (let j = 1n; j <= LINEAR_PROBES; j += 1n) {
        const idx = Number(i + j);
        if (table[idx] === undefined) {
          table[idx] = entry;
          return;
        }
      }
    }
    perturb >>= PERTURB_SHIFT;
    i = u64(i * 5n + 1n + perturb) & mask;
  }
}

/**
 * Replay CPython's insertion sequence and return the elements in table order.
 *
 * @param {Array<{hash: bigint, key: string, val: object}>} entries
 *        unique elements, in insertion order
 */
function cpythonOrder(entries) {
  let size = MIN_SIZE;
  let mask = BigInt(size - 1);
  let table = new Array(size);
  let fill = 0;

  for (const entry of entries) {
    // --- set_add_entry -----------------------------------------------------
    let perturb = u64(entry.hash);
    let i = u64(entry.hash) & mask;
    let placed = false;
    while (!placed) {
      const probes = i + LINEAR_PROBES <= mask ? Number(LINEAR_PROBES) : 0;
      for (let j = 0; j <= probes; j += 1) {
        const idx = Number(i) + j;
        if (table[idx] === undefined) {
          table[idx] = entry;
          placed = true;
          break;
        }
      }
      if (placed) break;
      perturb >>= PERTURB_SHIFT;
      i = u64(i * 5n + 1n + perturb) & mask;
    }
    fill += 1;

    // --- growth policy: `if ((size_t)fill*5 < mask*3) return;` -------------
    if (fill * 5 >= Number(mask) * 3) {
      const minused = fill > 50000 ? fill * 2 : fill * 4;
      let newsize = MIN_SIZE;
      while (newsize <= minused) newsize <<= 1;
      const oldTable = table;
      size = newsize;
      mask = BigInt(size - 1);
      table = new Array(size);
      for (const e of oldTable) {
        if (e !== undefined) insertClean(table, mask, e);
      }
    }
  }

  const out = [];
  for (const e of table) if (e !== undefined) out.push(e.val);
  return out;
}

export class PySet {
  constructor(tag) {
    this.t = tag;
    /** @type {Map<string, {hash: bigint|null, key: string, val: object}>} */
    this._map = new Map();
    /** True as soon as an element with a non-reproducible hash is added. */
    this._opaque = false;
  }

  static of(values, tag = T_SET) {
    const s = new PySet(tag);
    for (const v of values) s.add(v);
    return s;
  }

  get size() {
    return this._map.size;
  }

  add(v) {
    const key = hashKey(v);
    if (this._map.has(key)) return;
    const h = pyHash(v);
    if (h === null) this._opaque = true;
    this._map.set(key, { hash: h === null ? 0n : h, key, val: v });
  }

  has(v) {
    return this._map.has(hashKey(v));
  }

  discard(v) {
    this._map.delete(hashKey(v));
  }

  /** Elements in CPython iteration order (best effort — see module docstring). */
  items() {
    const entries = Array.from(this._map.values());
    if (this._opaque) return entries.map((e) => e.val);
    return cpythonOrder(entries);
  }

  copy(tag = this.t) {
    const s = new PySet(tag);
    for (const e of this._map.values()) s.add(e.val);
    return s;
  }
}

/**
 * Build a set the way CPython builds an all-constant set *display*.
 *
 * The compiler folds `{10, 2, 3}` into a `frozenset` constant and then emits
 * `BUILD_SET 0; LOAD_CONST frozenset; SET_UPDATE 1`, so the runtime set is
 * populated in the *frozenset's* table order, not source order.  That extra
 * hop genuinely changes the observable result (`{10, 2, 3}` iterates as
 * `2, 10, 3`), so it has to be modelled.
 */
export function buildConstantSetDisplay(values, tag = T_SET) {
  const folded = PySet.of(values, T_FROZENSET);
  return PySet.of(folded.items(), tag);
}

