/**
 * pyrepr.mjs
 *
 * `repr()` and `str()` for every value the evaluator can produce.  The source
 * program prints its results directly, so these functions decide whether the
 * output matches CPython byte for byte.
 */

import {
  T_BOOL,
  T_BYTES,
  T_COMPLEX,
  T_DICT,
  T_DICT_ITEMS,
  T_DICT_KEYS,
  T_DICT_VALUES,
  T_FLOAT,
  T_FROZENSET,
  T_FUNCTION,
  T_INT,
  T_LIST,
  T_NONE,
  T_RANGE,
  T_SET,
  T_STR,
  T_TUPLE,
  LAZY_TAGS,
} from './pyvalues.mjs';
import { floatRepr, formatDouble } from './floatrepr.mjs';

// `str.isprintable()` is false for Unicode "Other" (C*) and "Separator" (Z*)
// categories; the ASCII space is the single exception.
const NON_PRINTABLE = /^[\p{C}\p{Z}]$/u;

function isPrintableChar(ch) {
  if (ch === ' ') return true;
  return !NON_PRINTABLE.test(ch);
}

function escapeCodepoint(cp) {
  if (cp < 0x100) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp < 0x10000) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

/** CPython's `unicode_repr`, including its "smart quote" selection. */
export function strRepr(s) {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    if (ch === quote || ch === '\\') out += '\\' + ch;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (isPrintableChar(ch)) out += ch;
    else out += escapeCodepoint(ch.codePointAt(0));
  }
  return out + quote;
}

/** CPython's `bytes_repr`. */
export function bytesRepr(bytes) {
  const hasSingle = bytes.includes(0x27);
  const hasDouble = bytes.includes(0x22);
  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;
  const q = String.fromCharCode(quote);
  let out = 'b' + q;
  for (const c of bytes) {
    if (c === quote || c === 0x5c) out += '\\' + String.fromCharCode(c);
    else if (c === 0x09) out += '\\t';
    else if (c === 0x0a) out += '\\n';
    else if (c === 0x0d) out += '\\r';
    else if (c < 0x20 || c >= 0x7f) out += '\\x' + c.toString(16).padStart(2, '0');
    else out += String.fromCharCode(c);
  }
  return out + q;
}

/** CPython's `complex_repr` — note the parts skip the `.0` padding. */
export function complexRepr(re, im) {
  const signed = (x) => {
    const body = formatDouble(x, false);
    return body.startsWith('-') ? body : '+' + body;
  };
  if (re === 0 && !Object.is(re, -0)) {
    return formatDouble(im, false) + 'j';
  }
  return '(' + formatDouble(re, false) + signed(im) + 'j)';
