export function pyRepr(v) {
  // Objects that define their own repr (boltons OMD / FrozenDict).
  if (typeof v.pyRepr === 'function') return v.pyRepr();

  switch (v.t) {
    case T_NONE:
      return 'None';
    case T_BOOL:
      return v.v ? 'True' : 'False';
    case T_INT:
      return v.v.toString();
    case T_FLOAT:
      return floatRepr(v.v);
    case T_COMPLEX:
      return complexRepr(v.re, v.im);
    case T_STR:
      return strRepr(v.v);
    case T_BYTES:
      return bytesRepr(v.v);
    case T_LIST:
      return '[' + v.v.map(pyRepr).join(', ') + ']';
    case T_TUPLE:
      if (v.v.length === 0) return '()';
      if (v.v.length === 1) return '(' + pyRepr(v.v[0]) + ',)';
      return '(' + v.v.map(pyRepr).join(', ') + ')';
    case T_SET: {
      const items = v.items();
      if (items.length === 0) return 'set()';
      return '{' + items.map(pyRepr).join(', ') + '}';
    }
    case T_FROZENSET: {
      const items = v.items();
      if (items.length === 0) return 'frozenset()';
      return 'frozenset({' + items.map(pyRepr).join(', ') + '})';
    }
    case T_DICT:
      return dictRepr(v);
    case T_RANGE:
      return rangeRepr(v);
    case T_DICT_KEYS:
      return 'dict_keys([' + v.d.keys().map(pyRepr).join(', ') + '])';
    case T_DICT_VALUES:
      return 'dict_values([' + v.d.values().map(pyRepr).join(', ') + '])';
    case T_DICT_ITEMS:
      return (
        'dict_items([' +
        v.d
          .items()
          .map(([k, val]) => '(' + pyRepr(k) + ', ' + pyRepr(val) + ')')
          .join(', ') +
        '])'
      );
    case T_FUNCTION:
      return `<function ${v.name || '<lambda>'}>`;
    default:
      if (LAZY_TAGS.has(v.t)) return `<${v.t} object>`;
      return `<${v.t} object>`;
  }
}

