export function dictRepr(d) {
  const parts = d.items().map(([k, val]) => pyRepr(k) + ': ' + pyRepr(val));
  return '{' + parts.join(', ') + '}';
}

/**
 * `str()`.  Only `str` itself differs from `repr`; every type the source
 * program touches falls back to `__repr__` for `__str__`.
 */
export function pyStr(v) {
  if (v.t === T_STR) return v.v;
  return pyRepr(v);
}

