/**
 * pyops.mjs
 *
 * Python's operator semantics: numeric coercion (`bool` -> `int` -> `float` ->
 * `complex`), floor-based `//` and `%` (so `-1 % 2 == 1`, which the source
 * program's odd/even bucketing depends on), sequence `+`/`*`, chained
 * comparisons and `in`.
 */

import {
  NONE,
  T_BOOL,
  T_BYTES,
  T_COMPLEX,
  T_DICT,
  T_FLOAT,
  T_FROZENSET,
  T_INT,
  T_LIST,
  T_NONE,
  T_SET,
  T_STR,
  T_TUPLE,
  mkBool,
  mkBytes,
  mkComplex,
  mkFloat,
  mkInt,
  mkList,
  mkStr,
  mkTuple,
  strChars,
  truthy,
  typeError,
  zeroDivisionError,
} from './pyvalues.mjs';
import { PySet } from './pyset.mjs';
import { PyDict } from './pydict.mjs';
import { hashKey } from './pyhash.mjs';

const NUMERIC = new Set([T_BOOL, T_INT, T_FLOAT, T_COMPLEX]);

const isNumeric = (v) => NUMERIC.has(v.t);

/** Numeric rank used for coercion: 0 = integral, 1 = float, 2 = complex. */
function rank(v) {
  if (v.t === T_BOOL || v.t === T_INT) return 0;
  if (v.t === T_FLOAT) return 1;
  return 2;
}

export function asBigInt(v) {
  if (v.t === T_INT) return v.v;
  if (v.t === T_BOOL) return v.v ? 1n : 0n;
  throw typeError(`expected int, got '${v.t}'`);
}

export function asNumber(v) {
  if (v.t === T_INT) return Number(v.v);
  if (v.t === T_BOOL) return v.v ? 1 : 0;
  if (v.t === T_FLOAT) return v.v;
  throw typeError(`expected real number, got '${v.t}'`);
}

function asComplex(v) {
  if (v.t === T_COMPLEX) return [v.re, v.im];
  return [asNumber(v), 0];
}

// ---------------------------------------------------------------------------
// Integer helpers with Python's flooring semantics
// ---------------------------------------------------------------------------

export function bigFloorDiv(a, b) {
  if (b === 0n) throw zeroDivisionError('integer division or modulo by zero');
  let q = a / b;
  if (a % b !== 0n && a < 0n !== b < 0n) q -= 1n;
  return q;
}

export function bigMod(a, b) {
  if (b === 0n) throw zeroDivisionError('integer modulo by zero');
  const r = a % b;
  if (r !== 0n && r < 0n !== b < 0n) return r + b;
  return r;
}

function floatFloorDiv(a, b) {
  if (b === 0) throw zeroDivisionError('float floor division by zero');
  return Math.floor(a / b);
}

function floatMod(a, b) {
  if (b === 0) throw zeroDivisionError('float modulo');
  let mod = a % b; // JS % is truncating, like C fmod
  if (mod !== 0) {
    if (b < 0 !== mod < 0) mod += b;
  } else {
    mod = b < 0 ? -0 : 0;
  }
  return mod;
}

function bigPow(base, exp) {
  let result = 1n;
  let b = base;
  let e = exp;
  while (e > 0n) {
    if (e & 1n) result *= b;
    b *= b;
    e >>= 1n;
  }
  return result;
}

// ---------------------------------------------------------------------------
// Binary operators
// ---------------------------------------------------------------------------

function repeatSequence(seq, n) {
  const count = Number(asBigInt(n));
  const out = [];
  for (let i = 0; i < count; i += 1) out.push(...seq);
  return out;
}

export function binaryOp(op, a, b) {
  // --- sequence overloads ------------------------------------------------
  if (op === '+') {
    if (a.t === T_STR && b.t === T_STR) return mkStr(a.v + b.v);
    if (a.t === T_LIST && b.t === T_LIST) return mkList(a.v.concat(b.v));
    if (a.t === T_TUPLE && b.t === T_TUPLE) return mkTuple(a.v.concat(b.v));
    if (a.t === T_BYTES && b.t === T_BYTES) {
      const out = new Uint8Array(a.v.length + b.v.length);
      out.set(a.v, 0);
      out.set(b.v, a.v.length);
      return mkBytes(out);
    }
  }
  if (op === '*') {
    if (a.t === T_STR && (b.t === T_INT || b.t === T_BOOL)) {
      const n = Number(asBigInt(b));
      return mkStr(n > 0 ? a.v.repeat(n) : '');
    }
    if ((a.t === T_INT || a.t === T_BOOL) && b.t === T_STR) return binaryOp('*', b, a);
    if (a.t === T_LIST && (b.t === T_INT || b.t === T_BOOL)) return mkList(repeatSequence(a.v, b));
    if ((a.t === T_INT || a.t === T_BOOL) && b.t === T_LIST) return binaryOp('*', b, a);
    if (a.t === T_TUPLE && (b.t === T_INT || b.t === T_BOOL)) return mkTuple(repeatSequence(a.v, b));
    if ((a.t === T_INT || a.t === T_BOOL) && b.t === T_TUPLE) return binaryOp('*', b, a);
  }
  if (op === '%' && a.t === T_STR) return mkStr(printfFormat(a.v, b));

  // --- set algebra --------------------------------------------------------
  const setish = (x) => x.t === T_SET || x.t === T_FROZENSET;
  if (setish(a) && setish(b) && ['|', '&', '-', '^'].includes(op)) {
    const tag = a.t;
    const out = new PySet(tag);
    const bHas = (x) => b.has(x);
    if (op === '|') {
      for (const x of a.items()) out.add(x);
      for (const x of b.items()) out.add(x);
    } else if (op === '&') {
      for (const x of a.items()) if (bHas(x)) out.add(x);
    } else if (op === '-') {
      for (const x of a.items()) if (!bHas(x)) out.add(x);
    } else {
      for (const x of a.items()) if (!bHas(x)) out.add(x);
      for (const x of b.items()) if (!a.has(x)) out.add(x);
    }
    return out;
  }
  if (op === '|' && a.t === T_DICT && b.t === T_DICT) {
    const out = a.copy();
    for (const [k, v] of b.items()) out.set(k, v);
    return out;
  }

  if (!isNumeric(a) || !isNumeric(b)) {
