export function pyCompare(a, b) {
  if (isNumeric(a) && isNumeric(b)) {
    if (rank(a) === 0 && rank(b) === 0) {
      const x = asBigInt(a);
      const y = asBigInt(b);
      return x < y ? -1 : x > y ? 1 : 0;
