      const cx = xs[i].codePointAt(0);
      const cy = ys[i].codePointAt(0);
      if (cx !== cy) return cx < cy ? -1 : 1;
    }
    return xs.length === ys.length ? 0 : xs.length < ys.length ? -1 : 1;
  }
  if ((a.t === T_LIST && b.t === T_LIST) || (a.t === T_TUPLE && b.t === T_TUPLE)) {
    const n = Math.min(a.v.length, b.v.length);
    for (let i = 0; i < n; i += 1) {
      const c = pyCompare(a.v[i], b.v[i]);
      if (c !== 0) return c;
    }
