  switch (container.t) {
    case T_STR:
      if (item.t !== T_STR) throw typeError("'in <string>' requires string as left operand");
      return container.v.includes(item.v);
    case T_LIST:
    case T_TUPLE:
      return container.v.some((x) => pyEq(x, item));
    case T_SET:
    case T_FROZENSET:
      return container.has(item);
    case T_DICT:
      return container.has(item);
