  switch (op) {
    case '==':
      return mkBool(pyEq(a, b));
    case '!=':
      return mkBool(!pyEq(a, b));
    case '<':
      return mkBool(pyCompare(a, b) < 0);
    case '<=':
      return mkBool(pyCompare(a, b) <= 0);
    case '>':
      return mkBool(pyCompare(a, b) > 0);
    case '>=':
      return mkBool(pyCompare(a, b) >= 0);
    case 'in':
      return mkBool(contains(b, a));
    case 'not in':
      return mkBool(!contains(b, a));
