/**
 * pytokenizer.mjs
 *
 * Tokenizer for the Python *expression* grammar.  The source program feeds its
 * `--a` argument to `eval()`, so anything that is a valid Python expression can
 * legitimately show up: literals, displays, comprehensions, operators, calls,
 * lambdas and f-strings.
 */

import { syntaxError } from './pyvalues.mjs';

export const TOK_NAME = 'NAME';
export const TOK_NUMBER = 'NUMBER';
export const TOK_STRING = 'STRING';
export const TOK_OP = 'OP';
export const TOK_END = 'END';

// Longest-first so that `**` wins over `*`, `//=` over `//`, and so on.
const OPERATORS = [
  '**=', '//=', '>>=', '<<=', '...', '!=',
  '**', '//', '<<', '>>', '<=', '>=', '==', '->', ':=',
  '+=', '-=', '*=', '/=', '%=', '&=', '|=', '^=', '@=',
  '+', '-', '*', '/', '%', '@', '&', '|', '^', '~', '<', '>',
  '(', ')', '[', ']', '{', '}', ',', ':', '.', ';', '=',
];

const STRING_PREFIXES = new Set([
  '', 'r', 'b', 'u', 'f', 'rb', 'br', 'fr', 'rf', 'bu',
]);

const isDigit = (c) => c >= '0' && c <= '9';
const isIdentStart = (c) => /[A-Za-z_-￿]/.test(c);
const isIdentPart = (c) => /[A-Za-z0-9_-￿]/.test(c);

/**
 * @typedef {{type: string, value: string, pos: number,
 *            num?: {kind: string, value: any},
 *            str?: {prefix: string, body: string}}} Token
 */

export function tokenize(src) {
  /** @type {Token[]} */
  const tokens = [];
  let i = 0;
  const n = src.length;

  while (i < n) {
    const c = src[i];

    // Whitespace, line continuations and comments carry no meaning here.
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n' || c === '\f') {
      i += 1;
      continue;
    }
    if (c === '\\' && (src[i + 1] === '\n' || src[i + 1] === '\r')) {
      i += 2;
      continue;
    }
    if (c === '#') {
      while (i < n && src[i] !== '\n') i += 1;
      continue;
    }

    // ---- string literal (possibly prefixed) -------------------------------
    const prefixMatch = /^[A-Za-z]{0,2}(?=['"])/.exec(src.slice(i, i + 3));
    if (prefixMatch && prefixMatch[0] !== undefined && /['"]/.test(src[i + prefixMatch[0].length])) {
      const prefix = prefixMatch[0].toLowerCase();
      if (STRING_PREFIXES.has(prefix)) {
        const start = i;
        i += prefix.length;
        const { body, next } = readStringBody(src, i);
        i = next;
        tokens.push({ type: TOK_STRING, value: src.slice(start, i), pos: start, str: { prefix, body } });
        continue;
      }
    }

    // ---- number ------------------------------------------------------------
    if (isDigit(c) || (c === '.' && isDigit(src[i + 1]))) {
      const start = i;
      const num = readNumber(src, i);
      i = num.next;
      tokens.push({ type: TOK_NUMBER, value: src.slice(start, i), pos: start, num: num.token });
      continue;
    }

    // ---- identifier / keyword ---------------------------------------------
    if (isIdentStart(c)) {
      const start = i;
      i += 1;
      while (i < n && isIdentPart(src[i])) i += 1;
      tokens.push({ type: TOK_NAME, value: src.slice(start, i), pos: start });
      continue;
    }

    // ---- operator ----------------------------------------------------------
    let matched = null;
    for (const op of OPERATORS) {
      if (src.startsWith(op, i)) {
        matched = op;
        break;
      }
    }
    if (matched === null) throw syntaxError(`invalid character ${JSON.stringify(c)}`);
    tokens.push({ type: TOK_OP, value: matched, pos: i });
    i += matched.length;
  }

  tokens.push({ type: TOK_END, value: '', pos: n });
  return tokens;
}

/** Read the quoted portion of a string literal; returns the raw inner text. */
function readStringBody(src, i) {
  const quote = src[i];
  const triple = src.startsWith(quote.repeat(3), i);
  const delim = triple ? quote.repeat(3) : quote;
  let j = i + delim.length;
  let body = '';
  while (true) {
    if (j >= src.length) throw syntaxError('unterminated string literal');
    if (src.startsWith(delim, j)) return { body, next: j + delim.length };
    if (src[j] === '\\') {
      body += src[j] + (src[j + 1] ?? '');
      j += 2;
      continue;
    }
    if (!triple && (src[j] === '\n' || src[j] === '\r')) {
      throw syntaxError('unterminated string literal');
    }
    body += src[j];
    j += 1;
  }
}

function readNumber(src, i) {
  const n = src.length;
  const two = src.slice(i, i + 2).toLowerCase();

  const strip = (s) => s.replace(/_/g, '');

  if (two === '0x' || two === '0o' || two === '0b') {
    const radixChars = two === '0x' ? /[0-9a-fA-F_]/ : two === '0o' ? /[0-7_]/ : /[01_]/;
    let j = i + 2;
    while (j < n && radixChars.test(src[j])) j += 1;
    const digits = strip(src.slice(i + 2, j));
    const prefix = two === '0x' ? '0x' : two === '0o' ? '0o' : '0b';
    return { token: { kind: 'int', value: BigInt(prefix + digits) }, next: j };
  }

  let j = i;
  let isFloat = false;
  while (j < n && /[0-9_]/.test(src[j])) j += 1;
  if (src[j] === '.') {
    isFloat = true;
    j += 1;
    while (j < n && /[0-9_]/.test(src[j])) j += 1;
  }
  if (src[j] === 'e' || src[j] === 'E') {
    const save = j;
    let k = j + 1;
    if (src[k] === '+' || src[k] === '-') k += 1;
    if (isDigit(src[k])) {
      isFloat = true;
      j = k;
      while (j < n && /[0-9_]/.test(src[j])) j += 1;
    } else {
      j = save;
    }
  }
  const text = strip(src.slice(i, j));
  if (src[j] === 'j' || src[j] === 'J') {
    return { token: { kind: 'imag', value: Number(text) }, next: j + 1 };
  }
  if (isFloat) return { token: { kind: 'float', value: Number(text) }, next: j };
  return { token: { kind: 'int', value: BigInt(text) }, next: j };
}

// ---------------------------------------------------------------------------
// Escape-sequence decoding
// ---------------------------------------------------------------------------

const SIMPLE_ESCAPES = {
  '\n': '',
  '\\': '\\',
  "'": "'",
  '"': '"',
  a: '\x07',
  b: '\b',
  f: '\f',
  n: '\n',
  r: '\r',
  t: '\t',
  v: '\v',
  '0': '\0',
};

/** Decode a `str` literal body honouring the `r` prefix. */
export function decodeStrBody(body, raw) {
  if (raw) return body.replace(/\r\n/g, '\n');
  let out = '';
  let i = 0;
  while (i < body.length) {
    const c = body[i];
    if (c !== '\\') {
      out += c;
      i += 1;
      continue;
    }
    const e = body[i + 1];
    i += 2;
    if (e === 'x') {
      out += String.fromCharCode(parseInt(body.substr(i, 2), 16));
      i += 2;
    } else if (e === 'u') {
      out += String.fromCharCode(parseInt(body.substr(i, 4), 16));
      i += 4;
    } else if (e === 'U') {
      out += String.fromCodePoint(parseInt(body.substr(i, 8), 16));
      i += 8;
    } else if (e === 'N' && body[i] === '{') {
      const close = body.indexOf('}', i);
      i = close === -1 ? body.length : close + 1;
      out += '�';
    } else if (e >= '0' && e <= '7') {
      let oct = e;
      while (oct.length < 3 && body[i] >= '0' && body[i] <= '7') {
        oct += body[i];
        i += 1;
      }
      out += String.fromCharCode(parseInt(oct, 8));
    } else if (Object.prototype.hasOwnProperty.call(SIMPLE_ESCAPES, e)) {
      out += SIMPLE_ESCAPES[e];
    } else {
      out += '\\' + e; // unknown escapes are kept verbatim, as in CPython
    }
  }
  return out;
}

/** Decode a `bytes` literal body into raw octets. */
export function decodeBytesBody(body, raw) {
  const text = decodeStrBody(body, raw);
  const out = [];
  for (let i = 0; i < text.length; i += 1) out.push(text.charCodeAt(i) & 0xff);
  return new Uint8Array(out);
}

