/**
 * pyparser.mjs
 *
 * Recursive-descent parser for the Python expression grammar, producing a
 * small AST that pyeval.mjs walks.  Precedence and associativity follow the
 * reference grammar, including the two easy-to-get-wrong cases:
 *
 *   - `**` is right-associative and binds tighter than a leading unary minus,
 *     so `-2**2 == -4` while `2**-1 == 0.5`.
 *   - comparisons chain (`0 < x < 10`) and short-circuit.
 */

import { syntaxError } from './pyvalues.mjs';
import { TOK_END, TOK_NAME, TOK_NUMBER, TOK_OP, TOK_STRING, tokenize } from './pytokenizer.mjs';

const KEYWORDS = new Set([
  'and', 'or', 'not', 'in', 'is', 'if', 'else', 'for', 'lambda',
  'None', 'True', 'False', 'await', 'yield',
]);

class Parser {
  constructor(src) {
    this.tokens = tokenize(src);
    this.i = 0;
  }

  peek(offset = 0) {
    return this.tokens[Math.min(this.i + offset, this.tokens.length - 1)];
  }

  next() {
    const t = this.tokens[this.i];
    if (t.type !== TOK_END) this.i += 1;
    return t;
  }

  atOp(...ops) {
    const t = this.peek();
    return t.type === TOK_OP && ops.includes(t.value);
  }

  atName(...names) {
    const t = this.peek();
    return t.type === TOK_NAME && names.includes(t.value);
  }

  eatOp(op) {
    if (this.atOp(op)) {
      this.i += 1;
      return true;
    }
    return false;
  }

  eatName(name) {
    if (this.atName(name)) {
      this.i += 1;
      return true;
    }
    return false;
  }

  expectOp(op) {
    if (!this.eatOp(op)) throw syntaxError(`expected '${op}'`);
  }

  // -------------------------------------------------------------------------
  // Entry point: a whole expression, allowing a bare tuple (`1, 2`)
  // -------------------------------------------------------------------------

  parseTopLevel() {
    const node = this.parseExprListAllowBare();
    if (this.peek().type !== TOK_END) {
      throw syntaxError(`unexpected token '${this.peek().value}'`);
    }
    return node;
  }

  parseExprListAllowBare() {
    const first = this.parseTernaryOrStar();
    if (!this.atOp(',')) return first;
    const elts = [first];
    while (this.eatOp(',')) {
      if (this.peek().type === TOK_END) break;
      elts.push(this.parseTernaryOrStar());
    }
    return { kind: 'Tuple', elts, display: true };
  }

  parseTernaryOrStar() {
    if (this.atOp('*')) {
      this.next();
      return { kind: 'Starred', value: this.parseTernary() };
    }
    return this.parseTernary();
  }

  // -------------------------------------------------------------------------
  // lambda / conditional
  // -------------------------------------------------------------------------

  parseTernary() {
    if (this.atName('lambda')) return this.parseLambda();

    const body = this.parseOr();
    if (this.atName('if')) {
      // Careful: `x for y in z if c` is a comprehension guard, not a ternary.
      this.next();
      const test = this.parseOr();
      if (!this.eatName('else')) throw syntaxError("expected 'else' in conditional expression");
      const orelse = this.parseTernary();
      return { kind: 'IfExp', test, body, orelse };
    }
    return body;
  }

  parseLambda() {
    this.next(); // 'lambda'
    const params = [];
    const defaults = [];
    let starArg = null;
    let kwArg = null;
    while (!this.atOp(':')) {
      if (this.eatOp('*')) {
        if (this.peek().type === TOK_NAME) starArg = this.next().value;
      } else if (this.eatOp('**')) {
        kwArg = this.next().value;
      } else {
        const name = this.next();
        if (name.type !== TOK_NAME) throw syntaxError('invalid lambda parameter');
        params.push(name.value);
        defaults.push(this.eatOp('=') ? this.parseTernary() : null);
      }
      if (!this.eatOp(',')) break;
    }
    this.expectOp(':');
    const body = this.parseTernary();
    return { kind: 'Lambda', params, defaults, starArg, kwArg, body };
  }

  // -------------------------------------------------------------------------
  // Boolean / comparison
  // -------------------------------------------------------------------------

  parseOr() {
    let left = this.parseAnd();
    if (!this.atName('or')) return left;
    const values = [left];
    while (this.eatName('or')) values.push(this.parseAnd());
    return { kind: 'BoolOp', op: 'or', values };
  }

  parseAnd() {
    let left = this.parseNot();
    if (!this.atName('and')) return left;
    const values = [left];
    while (this.eatName('and')) values.push(this.parseNot());
    return { kind: 'BoolOp', op: 'and', values };
  }

  parseNot() {
    if (this.atName('not')) {
      this.next();
      return { kind: 'UnaryOp', op: 'not', operand: this.parseNot() };
    }
    return this.parseComparison();
  }

  readCompareOp() {
    const t = this.peek();
    if (t.type === TOK_OP && ['<', '>', '<=', '>=', '==', '!='].includes(t.value)) {
      this.next();
      return t.value;
    }
    if (t.type === TOK_NAME && t.value === 'in') {
      this.next();
      return 'in';
    }
    if (t.type === TOK_NAME && t.value === 'not' && this.peek(1).value === 'in') {
      this.next();
      this.next();
      return 'not in';
    }
    if (t.type === TOK_NAME && t.value === 'is') {
      this.next();
      if (this.eatName('not')) return 'is not';
      return 'is';
    }
    return null;
  }

  parseComparison() {
    const left = this.parseBitOr();
    const ops = [];
    const comparators = [];
    for (;;) {
      const op = this.readCompareOp();
      if (op === null) break;
      ops.push(op);
      comparators.push(this.parseBitOr());
    }
    if (ops.length === 0) return left;
    return { kind: 'Compare', left, ops, comparators };
  }

  // -------------------------------------------------------------------------
  // Arithmetic / bitwise, in precedence order
  // -------------------------------------------------------------------------

  binaryLevel(nextFn, ops) {
    let left = nextFn.call(this);
    while (this.atOp(...ops)) {
      const op = this.next().value;
      left = { kind: 'BinOp', op, left, right: nextFn.call(this) };
    }
    return left;
  }

  parseBitOr() {
    return this.binaryLevel(this.parseBitXor, ['|']);
  }

  parseBitXor() {
    return this.binaryLevel(this.parseBitAnd, ['^']);
  }

  parseBitAnd() {
    return this.binaryLevel(this.parseShift, ['&']);
  }

  parseShift() {
    return this.binaryLevel(this.parseArith, ['<<', '>>']);
  }

  parseArith() {
    return this.binaryLevel(this.parseTerm, ['+', '-']);
  }

  parseTerm() {
    return this.binaryLevel(this.parseFactor, ['*', '/', '//', '%', '@']);
  }

  /** factor: ('+'|'-'|'~') factor | power */
  parseFactor() {
    if (this.atOp('+', '-', '~')) {
      const op = this.next().value;
      return { kind: 'UnaryOp', op, operand: this.parseFactor() };
    }
    return this.parsePower();
  }

  /** power: primary ['**' factor]  (right-associative) */
  parsePower() {
    const base = this.parsePostfix();
    if (this.eatOp('**')) {
      return { kind: 'BinOp', op: '**', left: base, right: this.parseFactor() };
    }
    return base;
  }

  // -------------------------------------------------------------------------
  // Trailers
  // -------------------------------------------------------------------------

  parsePostfix() {
    let node = this.parseAtom();
    for (;;) {
      if (this.atOp('(')) {
        node = this.parseCall(node);
      } else if (this.atOp('[')) {
        this.next();
        const sub = this.parseSubscript();
        this.expectOp(']');
        node = { kind: 'Subscript', value: node, slice: sub };
      } else if (this.atOp('.')) {
        this.next();
        const name = this.next();
        if (name.type !== TOK_NAME) throw syntaxError('expected attribute name');
        node = { kind: 'Attribute', value: node, attr: name.value };
      } else {
        return node;
      }
    }
  }

  parseCall(func) {
    this.expectOp('(');
    const args = [];
    const keywords = [];
    while (!this.atOp(')')) {
      if (this.eatOp('**')) {
        keywords.push({ name: null, node: this.parseTernary() });
      } else if (this.eatOp('*')) {
        args.push({ star: true, node: this.parseTernary() });
      } else if (
        this.peek().type === TOK_NAME &&
        !KEYWORDS.has(this.peek().value) &&
        this.peek(1).type === TOK_OP &&
        this.peek(1).value === '='
      ) {
        const name = this.next().value;
        this.next(); // '='
        keywords.push({ name, node: this.parseTernary() });
      } else {
        const value = this.parseTernary();
        if (this.atName('for')) {
          const generators = this.parseComprehensionClauses();
          args.push({ node: { kind: 'GenExp', elt: value, generators } });
          continue;
        }
        args.push({ node: value });
      }
      if (!this.eatOp(',')) break;
    }
    this.expectOp(')');
    return { kind: 'Call', func, args, keywords };
  }

  parseSubscript() {
    const parseBound = () => (this.atOp(':', ']') ? null : this.parseTernary());
    const lower = parseBound();
    if (!this.atOp(':')) {
      // Possibly a tuple subscript: d[1, 2]
      if (this.atOp(',')) {
        const elts = [lower];
        while (this.eatOp(',')) {
          if (this.atOp(']')) break;
          elts.push(this.parseTernary());
        }
        return { kind: 'Tuple', elts, display: true };
      }
      return lower;
    }
    this.expectOp(':');
    const upper = parseBound();
    let step = null;
    if (this.eatOp(':')) step = parseBound();
    return { kind: 'Slice', lower, upper, step };
  }

  // -------------------------------------------------------------------------
  // Atoms
  // -------------------------------------------------------------------------

  parseAtom() {
    const t = this.peek();

    if (t.type === TOK_NUMBER) {
      this.next();
      return { kind: 'Num', num: t.num };
    }

    if (t.type === TOK_STRING) {
      return this.parseStringGroup();
    }

    if (t.type === TOK_NAME) {
      if (t.value === 'None' || t.value === 'True' || t.value === 'False') {
        this.next();
        return { kind: 'Const', name: t.value };
      }
      if (t.value === 'lambda') return this.parseLambda();
      if (t.value === 'not') return this.parseNot();
      this.next();
      return { kind: 'Name', id: t.value };
    }

    if (t.type === TOK_OP && t.value === '(') return this.parseParen();
    if (t.type === TOK_OP && t.value === '[') return this.parseListDisplay();
    if (t.type === TOK_OP && t.value === '{') return this.parseBraceDisplay();
    if (t.type === TOK_OP && t.value === '...') {
      this.next();
      return { kind: 'Const', name: 'Ellipsis' };
    }

    throw syntaxError(`unexpected token '${t.value || '<end>'}'`);
  }

  /** Adjacent string literals concatenate, as in `'a' 'b'`. */
  parseStringGroup() {
    const pieces = [];
    while (this.peek().type === TOK_STRING) {
      const tok = this.next();
      pieces.push({ prefix: tok.str.prefix, body: tok.str.body });
    }
    return { kind: 'Str', pieces };
  }

  parseParen() {
    this.expectOp('(');
    if (this.eatOp(')')) return { kind: 'Tuple', elts: [], display: true };

    const first = this.parseTernaryOrStar();
    if (this.atName('for')) {
      const generators = this.parseComprehensionClauses();
      this.expectOp(')');
      return { kind: 'GenExp', elt: first, generators };
    }
    if (this.atOp(',')) {
      const elts = [first];
      while (this.eatOp(',')) {
        if (this.atOp(')')) break;
        elts.push(this.parseTernaryOrStar());
      }
      this.expectOp(')');
      return { kind: 'Tuple', elts, display: true };
    }
    this.expectOp(')');
    return { kind: 'Paren', value: first };
  }

  parseListDisplay() {
    this.expectOp('[');
    if (this.eatOp(']')) return { kind: 'List', elts: [] };
    const first = this.parseTernaryOrStar();
    if (this.atName('for')) {
      const generators = this.parseComprehensionClauses();
      this.expectOp(']');
      return { kind: 'ListComp', elt: first, generators };
    }
    const elts = [first];
    while (this.eatOp(',')) {
      if (this.atOp(']')) break;
      elts.push(this.parseTernaryOrStar());
    }
    this.expectOp(']');
    return { kind: 'List', elts };
  }

  parseBraceDisplay() {
    this.expectOp('{');
    if (this.eatOp('}')) return { kind: 'Dict', keys: [], values: [] };

    // `{**d}` is unambiguously a dict.
    if (this.atOp('**')) {
      return this.parseDictRest(null, null);
    }

    if (this.atOp('*')) {
      // set display with unpacking
      const first = this.parseTernaryOrStar();
      return this.parseSetRest(first);
    }

    const first = this.parseTernary();
    if (this.atOp(':')) {
      this.next();
      const firstValue = this.parseTernary();
      if (this.atName('for')) {
        const generators = this.parseComprehensionClauses();
        this.expectOp('}');
        return { kind: 'DictComp', key: first, value: firstValue, generators };
      }
      return this.parseDictRest(first, firstValue);
    }
    if (this.atName('for')) {
      const generators = this.parseComprehensionClauses();
      this.expectOp('}');
      return { kind: 'SetComp', elt: first, generators };
    }
    return this.parseSetRest(first);
  }

  parseDictRest(firstKey, firstValue) {
    const keys = [];
    const values = [];
    if (firstKey !== null || firstValue !== null) {
      keys.push(firstKey);
      values.push(firstValue);
    }
    const readEntry = () => {
      if (this.eatOp('**')) {
        keys.push(null);
        values.push(this.parseTernary());
        return;
      }
      const k = this.parseTernary();
      this.expectOp(':');
      keys.push(k);
      values.push(this.parseTernary());
    };
    if (keys.length === 0) readEntry();
    while (this.eatOp(',')) {
      if (this.atOp('}')) break;
      readEntry();
    }
    this.expectOp('}');
    return { kind: 'Dict', keys, values };
  }

  parseSetRest(first) {
    const elts = [first];
    while (this.eatOp(',')) {
      if (this.atOp('}')) break;
      elts.push(this.parseTernaryOrStar());
    }
    this.expectOp('}');
    return { kind: 'Set', elts };
  }

  // -------------------------------------------------------------------------
  // Comprehension clauses
  // -------------------------------------------------------------------------

  parseComprehensionClauses() {
    const generators = [];
    while (this.atName('for')) {
      this.next();
      const target = this.parseTarget();
      if (!this.eatName('in')) throw syntaxError("expected 'in' in comprehension");
      const iter = this.parseOr();
      const ifs = [];
      while (this.atName('if')) {
        this.next();
        ifs.push(this.parseOrNoCond());
      }
      generators.push({ target, iter, ifs });
    }
    return generators;
  }

  /** A comprehension guard cannot itself be a bare conditional expression. */
  parseOrNoCond() {
    return this.parseOr();
  }

  parseTarget() {
    const readOne = () => {
      if (this.eatOp('(') || this.eatOp('[')) {
        const closing = this.tokens[this.i - 1].value === '(' ? ')' : ']';
        const elts = [];
        while (!this.atOp(closing)) {
          elts.push(readOne());
          if (!this.eatOp(',')) break;
        }
        this.expectOp(closing);
        return { kind: 'TargetTuple', elts };
      }
      if (this.eatOp('*')) {
        return { kind: 'TargetStar', value: readOne() };
      }
      const name = this.next();
      if (name.type !== TOK_NAME) throw syntaxError('invalid comprehension target');
      return { kind: 'TargetName', id: name.value };
    };

    const first = readOne();
    if (!this.atOp(',')) return first;
    const elts = [first];
    while (this.eatOp(',')) {
      if (this.atName('in')) break;
      elts.push(readOne());
    }
    return { kind: 'TargetTuple', elts };
  }
}

export function parseExpression(src) {
  const text = String(src).trim();
  if (text === '') throw syntaxError('unexpected EOF while parsing');
  return new Parser(text).parseTopLevel();
}

/**
 * Is this node a compile-time constant?
 *
 * CPython folds all-constant set displays into a `frozenset` constant, and that
 * changes the set's observable iteration order (see pyset.mjs), so the
 * evaluator needs to know.
 */
export function isConstantNode(node) {
  switch (node.kind) {
    case 'Num':
      return true;
    case 'Str':
      return node.pieces.every((p) => !p.prefix.includes('f'));
    case 'Const':
      return true;
    case 'Paren':
      return isConstantNode(node.value);
    case 'Tuple':
      return node.elts.every(isConstantNode);
    case 'UnaryOp':
      return node.op !== 'not' && isConstantNode(node.operand);
    case 'BinOp':
      return isConstantNode(node.left) && isConstantNode(node.right);
    default:
      return false;
  }
}

