  const [, fillRaw, alignRaw, sign, , zero, widthRaw, comma, precRaw, type] = m;
  const width = widthRaw ? Number(widthRaw) : 0;
  const prec = precRaw ? Number(precRaw) : undefined;

  if (type === 'f' || type === 'F') {
    const p = prec === undefined ? 6 : prec;
    text = asNumber(value).toFixed(p);
  } else if (type === 'd') {
    text = String(asBigInt(toInt(value)));
  } else if (type === 'x') text = asBigInt(value).toString(16);
  else if (type === 'X') text = asBigInt(value).toString(16).toUpperCase();
  else if (type === 'o') text = asBigInt(value).toString(8);
  else if (type === 'b') text = asBigInt(value).toString(2);
  else if (type === 'e' || type === 'E') {
    const p = prec === undefined ? 6 : prec;
    text = asNumber(value).toExponential(p);
    if (type === 'E') text = text.toUpperCase();
    text = text.replace(/e([+-])(\d)$/, 'e$10$2');
  } else if (type === '%') {
    const p = prec === undefined ? 6 : prec;
    text = (asNumber(value) * 100).toFixed(p) + '%';
  } else if (prec !== undefined && (type === undefined || type === 's')) {
    text = text.slice(0, prec);
  }

  if (comma) {
    const parts = text.split('.');
    parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
    text = parts.join('.');
  }
  if (sign === '+' && !text.startsWith('-')) text = '+' + text;
  if (sign === ' ' && !text.startsWith('-')) text = ' ' + text;

