 *
 * The builtin namespace and attribute/method dispatch for the `eval()`
 * sandbox.  `makeBuiltins(call)` takes the evaluator's function-invocation
 * helper so that higher-order builtins (`sorted(key=...)`, `map`, `filter`)
 * can call back into user lambdas without an import cycle.
 */

import {
  NONE,
  T_BOOL,
  T_BYTES,
  T_COMPLEX,
  T_DICT,
  T_DICT_ITEMS,
  T_DICT_KEYS,
  T_DICT_VALUES,
  T_FLOAT,
  T_FROZENSET,
  T_INT,
  T_LIST,
  T_NONE,
  T_RANGE,
  T_SET,
  T_STR,
  T_TUPLE,
  T_TYPE,
  attributeError,
  indexError,
  isIterable,
  iterValues,
  keyError,
  mkBool,
  mkBytes,
  mkComplex,
  mkFloat,
  mkInt,
  mkLazy,
  mkList,
  mkRange,
  mkStr,
  mkTuple,
  mkView,
  pyLen,
  strChars,
  stopIteration,
  toArray,
  truthy,
  typeError,
  valueError,
} from './pyvalues.mjs';
import { PyDict } from './pydict.mjs';
import { PySet } from './pyset.mjs';
import { pyRepr, pyStr } from './pyrepr.mjs';
import { asBigInt, asNumber, binaryOp, bigMod, bigFloorDiv, pyCompare, pyEq } from './pyops.mjs';

const mkBuiltin = (name, fn) => ({ t: 'builtin_function_or_method', name, fn });
const mkType = (name) => ({ t: T_TYPE, name });

const TYPE_TAGS = {
  int: [T_INT, T_BOOL],
  float: [T_FLOAT],
  str: [T_STR],
  bool: [T_BOOL],
  bytes: [T_BYTES],
  complex: [T_COMPLEX],
  list: [T_LIST],
  tuple: [T_TUPLE],
  dict: [T_DICT],
  set: [T_SET],
  frozenset: [T_FROZENSET],
  range: [T_RANGE],
  NoneType: [T_NONE],
  object: null, // matches everything
};

// ---------------------------------------------------------------------------
// Conversions
// ---------------------------------------------------------------------------

function toInt(v, base) {
  if (v === undefined) return mkInt(0n);
  if (v.t === T_STR) {
    const text = v.v.trim().replace(/_/g, '');
    const b = base === undefined ? 10 : Number(asBigInt(base));
    let body = text;
    let sign = 1n;
    if (body.startsWith('+')) body = body.slice(1);
    else if (body.startsWith('-')) {
      sign = -1n;
      body = body.slice(1);
    }
    let radix = b;
    const lower = body.toLowerCase();
    if (b === 16 || b === 0) {
      if (lower.startsWith('0x')) {
        body = body.slice(2);
        radix = 16;
      }
    }
    if (b === 8 || b === 0) {
      if (lower.startsWith('0o')) {
        body = body.slice(2);
        radix = 8;
      }
    }
    if (b === 2 || b === 0) {
      if (lower.startsWith('0b')) {
        body = body.slice(2);
        radix = 2;
      }
    }
    if (radix === 0) radix = 10;
    if (body === '') throw valueError(`invalid literal for int() with base ${b}: ${pyRepr(v)}`);
    let acc = 0n;
    const big = BigInt(radix);
    for (const ch of body) {
      const d = parseInt(ch, radix);
      if (Number.isNaN(d)) {
        throw valueError(`invalid literal for int() with base ${b}: ${pyRepr(v)}`);
      }
      acc = acc * big + BigInt(d);
    }
    return mkInt(sign * acc);
  }
  if (v.t === T_FLOAT) {
    if (!Number.isFinite(v.v)) {
      throw valueError('cannot convert float infinity/NaN to integer');
    }
    return mkInt(BigInt(Math.trunc(v.v)));
  }
  if (v.t === T_BOOL) return mkInt(v.v ? 1n : 0n);
  if (v.t === T_INT) return v;
  throw typeError(`int() argument must be a string or a number, not '${v.t}'`);
}

function toFloat(v) {
  if (v === undefined) return mkFloat(0);
  if (v.t === T_FLOAT) return v;
  if (v.t === T_INT) return mkFloat(Number(v.v));
  if (v.t === T_BOOL) return mkFloat(v.v ? 1 : 0);
  if (v.t === T_STR) {
    const text = v.v.trim().replace(/_/g, '');
    const lower = text.toLowerCase().replace(/^[+-]/, '');
    const neg = text.startsWith('-');
    if (lower === 'inf' || lower === 'infinity') return mkFloat(neg ? -Infinity : Infinity);
    if (lower === 'nan') return mkFloat(NaN);
    const x = Number(text);
    if (text === '' || Number.isNaN(x)) {
      throw valueError(`could not convert string to float: ${pyRepr(v)}`);
    }
    return mkFloat(x);
  }
  throw typeError(`float() argument must be a string or a number, not '${v.t}'`);
}

function toBytes(v) {
  if (v === undefined) return mkBytes([]);
  if (v.t === T_BYTES) return v;
  if (v.t === T_INT || v.t === T_BOOL) return mkBytes(new Uint8Array(Number(asBigInt(v))));
  if (v.t === T_STR) throw typeError('string argument without an encoding');
  const octets = toArray(v).map((x) => Number(asBigInt(x)) & 0xff);
  return mkBytes(octets);
}

/** `dict(...)` accepts a mapping, an iterable of pairs, or keyword arguments. */
function toDict(args, kwargs) {
  const d = new PyDict();
  if (args.length > 0) {
    const src = args[0];
    if (src.t === T_DICT) {
      for (const [k, v] of src.items()) d.set(k, v);
    } else if (typeof src.pyItems === 'function') {
      // boltons OMD / FrozenDict: dict() falls back to keys() + __getitem__
      for (const [k, v] of src.pyItems()) d.set(k, v);
    } else {
      for (const pair of iterValues(src)) {
        const parts = toArray(pair);
        if (parts.length !== 2) {
          throw valueError(`dictionary update sequence element has length ${parts.length}; 2 is required`);
        }
        d.set(parts[0], parts[1]);
      }
    }
  }
  for (const [name, value] of kwargs) d.set(mkStr(name), value);
  return d;
}

/** Python's `round`: banker's rounding, and `round(int)` stays an int. */
function pyRound(v, ndigits) {
  if (ndigits === undefined || ndigits.t === T_NONE) {
    if (v.t === T_INT || v.t === T_BOOL) return mkInt(asBigInt(v));
    const x = asNumber(v);
    const floor = Math.floor(x);
    const diff = x - floor;
    let r;
    if (diff > 0.5) r = floor + 1;
    else if (diff < 0.5) r = floor;
    else r = floor % 2 === 0 ? floor : floor + 1;
    return mkInt(BigInt(r));
  }
  const n = Number(asBigInt(ndigits));
  if (v.t === T_INT || v.t === T_BOOL) return mkInt(asBigInt(v));
  const x = asNumber(v);
  const scale = Math.pow(10, n);
  const scaled = x * scale;
  const floor = Math.floor(scaled);
  const diff = scaled - floor;
  let r;
  if (diff > 0.5) r = floor + 1;
  else if (diff < 0.5) r = floor;
  else r = floor % 2 === 0 ? floor : floor + 1;
  // Re-round through the decimal string to avoid binary-scaling artefacts.
  const candidate = r / scale;
  return mkFloat(Number(candidate.toFixed(Math.max(0, Math.min(100, n)))));
}

// ---------------------------------------------------------------------------
// Indexing helpers
// ---------------------------------------------------------------------------

function normaliseIndex(idx, length, forSlice) {
  let i = Number(asBigInt(idx));
  if (i < 0) i += length;
  if (forSlice) return Math.max(0, Math.min(length, i));
  if (i < 0 || i >= length) throw indexError('list index out of range');
  return i;
}

export function getItem(obj, key) {
  if (key.t === 'slice') return getSlice(obj, key);
  switch (obj.t) {
    case T_LIST:
    case T_TUPLE:
      return obj.v[normaliseIndex(key, obj.v.length, false)];
    case T_STR: {
      const chars = strChars(obj.v);
      return mkStr(chars[normaliseIndex(key, chars.length, false)]);
    }
    case T_BYTES:
      return mkInt(BigInt(obj.v[normaliseIndex(key, obj.v.length, false)]));
    case T_DICT: {
      if (!obj.has(key)) throw keyError(pyRepr(key));
      return obj.get(key);
    }
    case T_RANGE: {
      const n = pyLen(obj);
      const i = normaliseIndex(key, n, false);
      return mkInt(obj.start + obj.step * BigInt(i));
    }
    default:
      if (typeof obj.pyGetItem === 'function') return obj.pyGetItem(key);
      throw typeError(`'${obj.t}' object is not subscriptable`);
  }
}

function sliceBounds(sl, length) {
  const step = sl.step === null || sl.step.t === T_NONE ? 1 : Number(asBigInt(sl.step));
  if (step === 0) throw valueError('slice step cannot be zero');
  let start;
  let stop;
  if (step > 0) {
    start = sl.start === null || sl.start.t === T_NONE ? 0 : normaliseIndex(sl.start, length, true);
    stop = sl.stop === null || sl.stop.t === T_NONE ? length : normaliseIndex(sl.stop, length, true);
  } else {
    start =
      sl.start === null || sl.start.t === T_NONE
        ? length - 1
        : Math.min(length - 1, Math.max(-1, Number(asBigInt(sl.start)) < 0 ? Number(asBigInt(sl.start)) + length : Number(asBigInt(sl.start))));
    stop =
      sl.stop === null || sl.stop.t === T_NONE
        ? -1
        : Math.min(length - 1, Math.max(-1, Number(asBigInt(sl.stop)) < 0 ? Number(asBigInt(sl.stop)) + length : Number(asBigInt(sl.stop))));
  }
  return { start, stop, step };
}

function sliceIndices(sl, length) {
  const { start, stop, step } = sliceBounds(sl, length);
  const out = [];
  if (step > 0) for (let i = start; i < stop; i += step) out.push(i);
  else for (let i = start; i > stop; i += step) out.push(i);
  return out;
}

function getSlice(obj, sl) {
  switch (obj.t) {
    case T_LIST:
      return mkList(sliceIndices(sl, obj.v.length).map((i) => obj.v[i]));
    case T_TUPLE:
      return mkTuple(sliceIndices(sl, obj.v.length).map((i) => obj.v[i]));
    case T_STR: {
      const chars = strChars(obj.v);
      return mkStr(sliceIndices(sl, chars.length).map((i) => chars[i]).join(''));
    }
    case T_BYTES:
      return mkBytes(sliceIndices(sl, obj.v.length).map((i) => obj.v[i]));
    default:
      throw typeError(`'${obj.t}' object is not subscriptable`);
  }
}

// ---------------------------------------------------------------------------
// Builtin namespace
// ---------------------------------------------------------------------------

export function makeBuiltins(call) {
  const one = (args, name) => {
    if (args.length < 1) throw typeError(`${name}() takes exactly one argument`);
    return args[0];
  };

  const sortedWith = (items, keyFn, reverse) => {
    const decorated = items.map((v, i) => ({ v, i, k: keyFn ? call(keyFn, [v]) : v }));
    decorated.sort((a, b) => {
      const c = pyCompare(a.k, b.k);
      if (c !== 0) return c;
      return a.i - b.i; // stable
    });
    if (reverse) decorated.reverse();
    return decorated.map((d) => d.v);
  };

  const kw = (kwargs, name) => {
    for (const [k, v] of kwargs) if (k === name) return v;
    return undefined;
  };

  const B = new Map();
  const def = (name, fn) => B.set(name, mkBuiltin(name, fn));

  def('int', (args, kwargs) => toInt(args[0], args[1] ?? kw(kwargs, 'base')));
  def('float', (args) => toFloat(args[0]));
  def('str', (args) => (args.length === 0 ? mkStr('') : mkStr(pyStr(args[0]))));
  def('bool', (args) => (args.length === 0 ? mkBool(false) : mkBool(truthy(args[0]))));
  def('bytes', (args) => toBytes(args[0]));
  def('complex', (args) => {
    if (args.length === 0) return mkComplex(0, 0);
    if (args[0].t === T_COMPLEX && args.length === 1) return args[0];
    const re = args[0].t === T_COMPLEX ? args[0].re : asNumber(args[0]);
    const im = args.length > 1 ? asNumber(args[1]) : args[0].t === T_COMPLEX ? args[0].im : 0;
    return mkComplex(re, im);
  });
  def('list', (args) => mkList(args.length === 0 ? [] : toArray(args[0])));
  def('tuple', (args) => mkTuple(args.length === 0 ? [] : toArray(args[0])));
  def('set', (args) => PySet.of(args.length === 0 ? [] : toArray(args[0]), T_SET));
  def('frozenset', (args) => PySet.of(args.length === 0 ? [] : toArray(args[0]), T_FROZENSET));
  def('dict', (args, kwargs) => toDict(args, kwargs));

  def('range', (args) => {
    const nums = args.map((a) => asBigInt(a));
    if (nums.length === 1) return mkRange(0n, nums[0], 1n);
    if (nums.length === 2) return mkRange(nums[0], nums[1], 1n);
    if (nums.length >= 3) return mkRange(nums[0], nums[1], nums[2]);
    throw typeError('range expected at least 1 argument, got 0');
  });

  def('len', (args) => mkInt(BigInt(pyLen(one(args, 'len')))));
  def('repr', (args) => mkStr(pyRepr(one(args, 'repr'))));
  def('abs', (args) => {
    const v = one(args, 'abs');
    if (v.t === T_COMPLEX) return mkFloat(Math.hypot(v.re, v.im));
    if (v.t === T_FLOAT) return mkFloat(Math.abs(v.v));
    const b = asBigInt(v);
    return mkInt(b < 0n ? -b : b);
  });
  def('round', (args, kwargs) => pyRound(args[0], args[1] ?? kw(kwargs, 'ndigits')));
  def('sum', (args) => {
    let acc = args.length > 1 ? args[1] : mkInt(0n);
    for (const item of iterValues(args[0])) acc = binaryOp('+', acc, item);
    return acc;
  });
  def('min', (args, kwargs) => {
    const items = args.length === 1 ? toArray(args[0]) : args;
    if (items.length === 0) throw valueError('min() arg is an empty sequence');
    return sortedWith(items, kw(kwargs, 'key'), false)[0];
  });
  def('max', (args, kwargs) => {
    const items = args.length === 1 ? toArray(args[0]) : args;
    if (items.length === 0) throw valueError('max() arg is an empty sequence');
    const s = sortedWith(items, kw(kwargs, 'key'), false);
    return s[s.length - 1];
  });
  def('sorted', (args, kwargs) => {
    const reverse = kw(kwargs, 'reverse');
    return mkList(sortedWith(toArray(args[0]), kw(kwargs, 'key'), reverse ? truthy(reverse) : false));
  });
  def('reversed', (args) => {
    const items = toArray(args[0]).slice().reverse();
    return mkLazy('reversed', items[Symbol.iterator]());
  });
  def('enumerate', (args, kwargs) => {
    const startArg = args[1] ?? kw(kwargs, 'start');
    let idx = startArg === undefined ? 0n : asBigInt(startArg);
    const it = iterValues(args[0])[Symbol.iterator]();
    function* gen() {
      for (;;) {
        const step = it.next();
        if (step.done) return;
        yield mkTuple([mkInt(idx), step.value]);
        idx += 1n;
      }
    }
    return mkLazy('enumerate', gen());
  });
  def('zip', (args) => {
    const iters = args.map((a) => iterValues(a)[Symbol.iterator]());
    function* gen() {
      for (;;) {
        const row = [];
        for (const it of iters) {
          const step = it.next();
          if (step.done) return;
          row.push(step.value);
        }
        if (row.length === 0) return;
        yield mkTuple(row);
      }
    }
    return mkLazy('zip', gen());
  });
  def('map', (args) => {
    const fn = args[0];
    const iters = args.slice(1).map((a) => iterValues(a)[Symbol.iterator]());
    function* gen() {
      for (;;) {
        const row = [];
        for (const it of iters) {
          const step = it.next();
          if (step.done) return;
          row.push(step.value);
        }
        yield call(fn, row);
      }
    }
    return mkLazy('map', gen());
  });
  def('filter', (args) => {
    const fn = args[0];
    const it = iterValues(args[1])[Symbol.iterator]();
    function* gen() {
      for (;;) {
        const step = it.next();
        if (step.done) return;
        const keep = fn.t === T_NONE ? truthy(step.value) : truthy(call(fn, [step.value]));
        if (keep) yield step.value;
      }
    }
    return mkLazy('filter', gen());
  });
  def('any', (args) => {
    for (const x of iterValues(args[0])) if (truthy(x)) return mkBool(true);
    return mkBool(false);
  });
  def('all', (args) => {
    for (const x of iterValues(args[0])) if (!truthy(x)) return mkBool(false);
    return mkBool(true);
  });
  def('chr', (args) => mkStr(String.fromCodePoint(Number(asBigInt(args[0])))));
  def('ord', (args) => {
    const v = args[0];
    if (v.t === T_BYTES) return mkInt(BigInt(v.v[0]));
    const chars = strChars(v.v);
    if (chars.length !== 1) throw typeError('ord() expected a character');
    return mkInt(BigInt(chars[0].codePointAt(0)));
  });
  def('hex', (args) => {
    const b = asBigInt(args[0]);
    return mkStr(b < 0n ? '-0x' + (-b).toString(16) : '0x' + b.toString(16));
  });
  def('oct', (args) => {
    const b = asBigInt(args[0]);
    return mkStr(b < 0n ? '-0o' + (-b).toString(8) : '0o' + b.toString(8));
  });
  def('bin', (args) => {
    const b = asBigInt(args[0]);
    return mkStr(b < 0n ? '-0b' + (-b).toString(2) : '0b' + b.toString(2));
  });
  def('divmod', (args) => {
    const [a, b] = args;
    if (a.t === T_FLOAT || b.t === T_FLOAT) {
      return mkTuple([binaryOp('//', a, b), binaryOp('%', a, b)]);
    }
    return mkTuple([mkInt(bigFloorDiv(asBigInt(a), asBigInt(b))), mkInt(bigMod(asBigInt(a), asBigInt(b)))]);
  });
  def('pow', (args) => binaryOp('**', args[0], args[1]));
  def('type', (args) => mkType(one(args, 'type').t));
  def('isinstance', (args) => {
    const [v, cls] = args;
    const classes = cls.t === T_TUPLE ? cls.v : [cls];
    return mkBool(
      classes.some((c) => {
        const tags = TYPE_TAGS[c.name];
        if (tags === null) return true;
        if (tags === undefined) return v.t === c.name;
        return tags.includes(v.t);
      }),
    );
  });
  def('iter', (args) => {
    const v = args[0];
    if (!isIterable(v)) throw typeError(`'${v.t}' object is not iterable`);
    return mkLazy('list_iterator', iterValues(v)[Symbol.iterator]());
  });
  def('next', (args) => {
    const it = args[0];
    if (it.it === undefined) throw typeError(`'${it.t}' object is not an iterator`);
    const step = it.it.next();
    if (step.done) {
      if (args.length > 1) return args[1];
      throw stopIteration();
    }
    return step.value;
  });
  def('print', (args) => {
    process.stdout.write(args.map(pyStr).join(' ') + '\n');
    return NONE;
  });

  // Type objects, so `isinstance(x, int)` and `int('5')` share one name.
  for (const name of Object.keys(TYPE_TAGS)) {
    const existing = B.get(name);
    const typeObj = mkType(name);
    if (existing) {
      // Callable *and* usable as a class in isinstance().
      B.set(name, { t: T_TYPE, name, fn: existing.fn });
    } else {
      B.set(name, typeObj);
    }
  }

  return B;
}

// ---------------------------------------------------------------------------
// Attribute / method access
// ---------------------------------------------------------------------------

export function getAttribute(obj, name, call) {
  if (obj.t === T_TYPE && name === '__name__') return mkStr(obj.name);

  const method = lookupMethod(obj, name, call);
  if (method !== undefined) return method;

  if (typeof obj.pyGetAttr === 'function') {
    const found = obj.pyGetAttr(name, call);
    if (found !== undefined) return found;
  }
  throw attributeError(`'${obj.t}' object has no attribute '${name}'`);
}

function bound(name, fn) {
  return mkBuiltin(name, fn);
}

function lookupMethod(obj, name, call) {
  switch (obj.t) {
    case T_STR:
      return strMethod(obj, name);
    case T_LIST:
      return listMethod(obj, name, call);
    case T_TUPLE:
      return tupleMethod(obj, name);
    case T_DICT:
      return dictMethod(obj, name);
    case T_SET:
    case T_FROZENSET:
      return setMethod(obj, name);
    case T_BYTES:
      return bytesMethod(obj, name);
    case T_DICT_KEYS:
    case T_DICT_VALUES:
    case T_DICT_ITEMS:
      return undefined;
    default:
      return undefined;
  }
}

function strMethod(obj, name) {
  const s = obj.v;
  const table = {
    upper: () => mkStr(s.toUpperCase()),
    lower: () => mkStr(s.toLowerCase()),
    title: () => mkStr(s.replace(/[A-Za-z]+/g, (w) => w[0].toUpperCase() + w.slice(1).toLowerCase())),
    capitalize: () => mkStr(s.length ? s[0].toUpperCase() + s.slice(1).toLowerCase() : s),
    swapcase: () =>
      mkStr(
        Array.from(s, (c) => (c === c.toUpperCase() ? c.toLowerCase() : c.toUpperCase())).join(''),
      ),
    strip: (args) => mkStr(trimWith(s, args[0], true, true)),
    lstrip: (args) => mkStr(trimWith(s, args[0], true, false)),
    rstrip: (args) => mkStr(trimWith(s, args[0], false, true)),
    split: (args) => mkList(splitString(s, args[0], args[1]).map(mkStr)),
    rsplit: (args) => mkList(splitString(s, args[0], args[1], true).map(mkStr)),
    splitlines: () => mkList(s.split(/\r\n|\r|\n/).filter((p, i, a) => !(p === '' && i === a.length - 1)).map(mkStr)),
    join: (args) => mkStr(toArray(args[0]).map((x) => x.v).join(s)),
    replace: (args) => {
      const [from, to, count] = args;
      if (count === undefined) return mkStr(s.split(from.v).join(to.v));
      let n = Number(asBigInt(count));
      let out = s;
      let result = '';
      while (n > 0) {
        const idx = out.indexOf(from.v);
        if (idx === -1) break;
        result += out.slice(0, idx) + to.v;
        out = out.slice(idx + from.v.length);
        n -= 1;
      }
      return mkStr(result + out);
    },
    startswith: (args) => {
      const prefixes = args[0].t === T_TUPLE ? args[0].v : [args[0]];
      return mkBool(prefixes.some((p) => s.startsWith(p.v)));
    },
    endswith: (args) => {
      const suffixes = args[0].t === T_TUPLE ? args[0].v : [args[0]];
      return mkBool(suffixes.some((p) => s.endsWith(p.v)));
    },
    find: (args) => mkInt(BigInt(s.indexOf(args[0].v))),
    rfind: (args) => mkInt(BigInt(s.lastIndexOf(args[0].v))),
    index: (args) => {
      const i = s.indexOf(args[0].v);
      if (i === -1) throw valueError('substring not found');
      return mkInt(BigInt(i));
    },
    count: (args) => {
      if (args[0].v === '') return mkInt(BigInt(strChars(s).length + 1));
      return mkInt(BigInt(s.split(args[0].v).length - 1));
    },
    zfill: (args) => mkStr(s.padStart(Number(asBigInt(args[0])), '0')),
    ljust: (args) => mkStr(s.padEnd(Number(asBigInt(args[0])), args[1] ? args[1].v : ' ')),
    rjust: (args) => mkStr(s.padStart(Number(asBigInt(args[0])), args[1] ? args[1].v : ' ')),
    center: (args) => {
      const width = Number(asBigInt(args[0]));
      const fill = args[1] ? args[1].v : ' ';
      const total = width - strChars(s).length;
      if (total <= 0) return mkStr(s);
      const left = Math.floor(total / 2);
      return mkStr(fill.repeat(left) + s + fill.repeat(total - left));
    },
    isdigit: () => mkBool(s.length > 0 && /^[0-9]+$/.test(s)),
    isalpha: () => mkBool(s.length > 0 && /^\p{L}+$/u.test(s)),
    isalnum: () => mkBool(s.length > 0 && /^[\p{L}\p{N}]+$/u.test(s)),
    isspace: () => mkBool(s.length > 0 && /^\s+$/.test(s)),
    isupper: () => mkBool(/\p{L}/u.test(s) && s === s.toUpperCase()),
    islower: () => mkBool(/\p{L}/u.test(s) && s === s.toLowerCase()),
    encode: () => mkBytes(new TextEncoder().encode(s)),
    format: (args, kwargs) => mkStr(strFormat(s, args, kwargs)),
  };
  const fn = table[name];
  return fn === undefined ? undefined : bound(name, fn);
}

function trimWith(s, chars, left, right) {
  if (chars === undefined || chars.t === T_NONE) {
    let out = s;
    if (left) out = out.replace(/^\s+/, '');
    if (right) out = out.replace(/\s+$/, '');
    return out;
  }
  const set = new Set(strChars(chars.v));
  let start = 0;
  let end = s.length;
  if (left) while (start < end && set.has(s[start])) start += 1;
  if (right) while (end > start && set.has(s[end - 1])) end -= 1;
  return s.slice(start, end);
}

function splitString(s, sep, maxsplit, fromRight = false) {
  const limit = maxsplit === undefined || maxsplit.t === T_NONE ? -1 : Number(asBigInt(maxsplit));
  if (sep === undefined || sep.t === T_NONE) {
    const parts = s.split(/\s+/).filter((p) => p !== '');
    if (limit < 0) return parts;
    // Whitespace splitting with a limit keeps the tail intact.
    const trimmed = s.replace(/^\s+/, '');
    const out = [];
    let rest = trimmed;
    while (out.length < limit) {
      const m = /\s+/.exec(rest);
      if (!m) break;
      out.push(rest.slice(0, m.index));
      rest = rest.slice(m.index + m[0].length);
    }
    out.push(rest);
    return out;
  }
  const all = s.split(sep.v);
  if (limit < 0 || all.length <= limit + 1) return all;
  if (!fromRight) {
    const head = all.slice(0, limit);
    head.push(all.slice(limit).join(sep.v));
    return head;
  }
  const tail = all.slice(all.length - limit);
  return [all.slice(0, all.length - limit).join(sep.v), ...tail];
}

/** `str.format` with positional `{}`/`{0}` and named `{name}` fields. */
function strFormat(fmt, args, kwargs) {
  let auto = 0;
  return fmt.replace(/\{\{|\}\}|\{([^{}]*)\}/g, (m, field) => {
    if (m === '{{') return '{';
    if (m === '}}') return '}';
    let spec = '';
    let conv = '';
    let body = field;
    const colon = body.indexOf(':');
    if (colon !== -1) {
      spec = body.slice(colon + 1);
      body = body.slice(0, colon);
    }
    const bang = body.indexOf('!');
    if (bang !== -1) {
      conv = body.slice(bang + 1);
      body = body.slice(0, bang);
    }
    let value;
    if (body === '') {
      value = args[auto];
      auto += 1;
    } else if (/^\d+$/.test(body)) {
      value = args[Number(body)];
    } else {
      for (const [k, v] of kwargs) if (k === body) value = v;
    }
    if (value === undefined) return '';
    return applyFormatSpec(value, spec, conv);
  });
}

export function applyFormatSpec(value, spec, conv) {
  let text;
  if (conv === 'r') text = pyRepr(value);
  else if (conv === 'a') text = pyRepr(value);
  else text = pyStr(value);

  if (!spec) return text;
  const m = /^(?:(.)?([<>^=]))?([+\- ])?(#)?(0)?(\d+)?(,)?(?:\.(\d+))?([bcdeEfFgGnosxX%])?$/.exec(spec);
  if (!m) return text;
  const [, fillRaw, alignRaw, sign, , zero, widthRaw, comma, precRaw, type] = m;
  const width = widthRaw ? Number(widthRaw) : 0;
  const prec = precRaw ? Number(precRaw) : undefined;

  if (type === 'f' || type === 'F') {
    const p = prec === undefined ? 6 : prec;
    text = asNumber(value).toFixed(p);
  } else if (type === 'd') {
    text = String(asBigInt(toInt(value)));
  } else if (type === 'x') text = asBigInt(value).toString(16);
  else if (type === 'X') text = asBigInt(value).toString(16).toUpperCase();
  else if (type === 'o') text = asBigInt(value).toString(8);
  else if (type === 'b') text = asBigInt(value).toString(2);
  else if (type === 'e' || type === 'E') {
    const p = prec === undefined ? 6 : prec;
    text = asNumber(value).toExponential(p);
    if (type === 'E') text = text.toUpperCase();
    text = text.replace(/e([+-])(\d)$/, 'e$10$2');
  } else if (type === '%') {
    const p = prec === undefined ? 6 : prec;
    text = (asNumber(value) * 100).toFixed(p) + '%';
  } else if (prec !== undefined && (type === undefined || type === 's')) {
    text = text.slice(0, prec);
  }

  if (comma) {
    const parts = text.split('.');
    parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
    text = parts.join('.');
  }
  if (sign === '+' && !text.startsWith('-')) text = '+' + text;
  if (sign === ' ' && !text.startsWith('-')) text = ' ' + text;

  const fill = fillRaw || (zero ? '0' : ' ');
  const align = alignRaw || (zero ? '=' : typeof value === 'object' && ['int', 'float', 'bool'].includes(value.t) ? '>' : '<');
  if (width > text.length) {
    const pad = width - text.length;
    if (align === '>' || align === '=') text = fill.repeat(pad) + text;
    else if (align === '^') {
      const left = Math.floor(pad / 2);
      text = fill.repeat(left) + text + fill.repeat(pad - left);
    } else text = text + fill.repeat(pad);
  }
  return text;
}

function listMethod(obj, name, call) {
  const table = {
    append: (args) => {
      obj.v.push(args[0]);
      return NONE;
    },
    extend: (args) => {
      obj.v.push(...toArray(args[0]));
      return NONE;
    },
    insert: (args) => {
      obj.v.splice(Number(asBigInt(args[0])), 0, args[1]);
      return NONE;
    },
    pop: (args) => {
      const i = args.length ? normaliseIndex(args[0], obj.v.length, false) : obj.v.length - 1;
      if (obj.v.length === 0) throw indexError('pop from empty list');
      return obj.v.splice(i, 1)[0];
    },
    remove: (args) => {
      const i = obj.v.findIndex((x) => pyEq(x, args[0]));
      if (i === -1) throw valueError('list.remove(x): x not in list');
      obj.v.splice(i, 1);
      return NONE;
    },
    index: (args) => {
      const i = obj.v.findIndex((x) => pyEq(x, args[0]));
      if (i === -1) throw valueError(`${pyRepr(args[0])} is not in list`);
      return mkInt(BigInt(i));
    },
    count: (args) => mkInt(BigInt(obj.v.filter((x) => pyEq(x, args[0])).length)),
    reverse: () => {
      obj.v.reverse();
      return NONE;
    },
    sort: (args, kwargs) => {
      let keyFn;
      let reverse = false;
      for (const [k, v] of kwargs) {
        if (k === 'key') keyFn = v;
        if (k === 'reverse') reverse = truthy(v);
      }
      const decorated = obj.v.map((v, i) => ({ v, i, k: keyFn ? call(keyFn, [v]) : v }));
      decorated.sort((a, b) => {
        const c = pyCompare(a.k, b.k);
        return c !== 0 ? c : a.i - b.i;
      });
      if (reverse) decorated.reverse();
      obj.v.length = 0;
      obj.v.push(...decorated.map((d) => d.v));
      return NONE;
    },
    copy: () => mkList(obj.v.slice()),
    clear: () => {
      obj.v.length = 0;
      return NONE;
    },
  };
  const fn = table[name];
  return fn === undefined ? undefined : bound(name, fn);
}

function tupleMethod(obj, name) {
  const table = {
    count: (args) => mkInt(BigInt(obj.v.filter((x) => pyEq(x, args[0])).length)),
    index: (args) => {
      const i = obj.v.findIndex((x) => pyEq(x, args[0]));
      if (i === -1) throw valueError('tuple.index(x): x not in tuple');
      return mkInt(BigInt(i));
    },
  };
  const fn = table[name];
  return fn === undefined ? undefined : bound(name, fn);
}

function dictMethod(obj, name) {
  const table = {
    keys: () => mkView(T_DICT_KEYS, obj),
    values: () => mkView(T_DICT_VALUES, obj),
    items: () => mkView(T_DICT_ITEMS, obj),
    get: (args) => obj.getOr(args[0], args.length > 1 ? args[1] : NONE),
    setdefault: (args) => obj.setdefault(args[0], args.length > 1 ? args[1] : NONE),
    pop: (args) => {
      if (obj.has(args[0])) {
        const v = obj.get(args[0]);
        obj.delete(args[0]);
        return v;
      }
      if (args.length > 1) return args[1];
      throw keyError(pyRepr(args[0]));
    },
    update: (args, kwargs) => {
      if (args.length) {
        const src = args[0];
        if (src.t === T_DICT) for (const [k, v] of src.items()) obj.set(k, v);
        else
          for (const pair of iterValues(src)) {
            const parts = toArray(pair);
            obj.set(parts[0], parts[1]);
          }
      }
      for (const [k, v] of kwargs) obj.set(mkStr(k), v);
      return NONE;
    },
    copy: () => obj.copy(),
    clear: () => {
      for (const k of obj.keys()) obj.delete(k);
      return NONE;
    },
  };
  const fn = table[name];
  return fn === undefined ? undefined : bound(name, fn);
}

function setMethod(obj, name) {
  const table = {
    add: (args) => {
      obj.add(args[0]);
      return NONE;
    },
    discard: (args) => {
      obj.discard(args[0]);
      return NONE;
    },
    remove: (args) => {
      if (!obj.has(args[0])) throw keyError(pyRepr(args[0]));
      obj.discard(args[0]);
      return NONE;
    },
    update: (args) => {
      for (const a of args) for (const x of iterValues(a)) obj.add(x);
      return NONE;
    },
    union: (args) => {
      const out = obj.copy(T_SET);
      for (const a of args) for (const x of iterValues(a)) out.add(x);
      return out;
    },
    intersection: (args) => {
      let out = obj.copy(T_SET);
      for (const a of args) {
        const other = PySet.of(toArray(a), T_SET);
        const next = new PySet(T_SET);
        for (const x of out.items()) if (other.has(x)) next.add(x);
        out = next;
      }
      return out;
    },
    difference: (args) => {
      const out = new PySet(T_SET);
      const others = args.map((a) => PySet.of(toArray(a), T_SET));
      for (const x of obj.items()) if (!others.some((o) => o.has(x))) out.add(x);
      return out;
    },
    symmetric_difference: (args) => binaryOp('^', obj, PySet.of(toArray(args[0]), T_SET)),
    issubset: (args) => {
      const other = PySet.of(toArray(args[0]), T_SET);
      return mkBool(obj.items().every((x) => other.has(x)));
    },
    issuperset: (args) => mkBool(toArray(args[0]).every((x) => obj.has(x))),
    isdisjoint: (args) => mkBool(!toArray(args[0]).some((x) => obj.has(x))),
    copy: () => obj.copy(),
    clear: () => {
      for (const x of obj.items()) obj.discard(x);
      return NONE;
    },
  };
  const fn = table[name];
  return fn === undefined ? undefined : bound(name, fn);
}

function bytesMethod(obj, name) {
  const table = {
    decode: () => mkStr(new TextDecoder().decode(obj.v)),
    hex: () => mkStr(Array.from(obj.v, (b) => b.toString(16).padStart(2, '0')).join('')),
  };
  const fn = table[name];
  return fn === undefined ? undefined : bound(name, fn);
}

