          : `too many values to unpack (expected ${elts.length})`,
      );
    }
    elts.forEach((e, i) => bindTarget(e, items[i], scope));
    return;
  }
  const before = elts.slice(0, starIndex);
  const after = elts.slice(starIndex + 1);
  before.forEach((e, i) => bindTarget(e, items[i], scope));
  const rest = items.slice(before.length, items.length - after.length);
  bindTarget(elts[starIndex].value, mkList(rest), scope);
  after.forEach((e, i) => bindTarget(e, items[items.length - after.length + i], scope));
}

/** Scan `{expr!conv:spec}` starting at `body[start] === '{'`. */
function scanReplacementField(body, start) {
  let depth = 0;
  let i = start;
  let quote = null;
  let exprEnd = -1;
  let conv = '';
  let spec = '';
  let bangAt = -1;
  let colonAt = -1;

  for (; i < body.length; i += 1) {
    const c = body[i];
    if (quote) {
      if (c === quote) quote = null;
      continue;
    }
    if (c === "'" || c === '"') {
      quote = c;
      continue;
    }
    if (c === '{' || c === '[' || c === '(') {
      depth += 1;
      continue;
    }
    if (c === '}' && depth === 1) {
      exprEnd = i;
      break;
    }
    if (c === '}' || c === ']' || c === ')') {
      depth -= 1;
      continue;
    }
    if (depth === 1 && c === '!' && body[i + 1] !== '=' && colonAt === -1 && bangAt === -1) {
      bangAt = i;
      continue;
    }
    if (depth === 1 && c === ':' && colonAt === -1) {
      colonAt = i;
      continue;
    }
  }
  if (exprEnd === -1) throw syntaxError("f-string: expecting '}'");

  const cut = bangAt !== -1 ? bangAt : colonAt !== -1 ? colonAt : exprEnd;
  const expr = body.slice(start + 1, cut);
  if (bangAt !== -1) conv = body.slice(bangAt + 1, colonAt !== -1 ? colonAt : exprEnd);
  if (colonAt !== -1) spec = body.slice(colonAt + 1, exprEnd);
  return { expr, conv, spec, next: exprEnd + 1 };
}

/** Evaluate a Python expression string, mirroring the source program's `eval`. */
export function pyEval(source) {
  return new Evaluator().run(source);
}

