/**
 * pyeval.mjs
 *
 * Tree-walking evaluator for the parsed Python expression, i.e. the `eval()`
 * that the source program applies to its `--a` argument.
 */

import {
  NONE,
  T_BOOL,
  T_BYTES,
  T_DICT,
  T_FROZENSET,
  T_INT,
  T_LIST,
  T_SET,
  T_STR,
  T_TUPLE,
  T_TYPE,
  isIterable,
  iterValues,
  mkBool,
  mkBytes,
  mkComplex,
  mkFloat,
  mkInt,
  mkLazy,
  mkList,
  mkSlice,
  mkStr,
  mkTuple,
  nameError,
  syntaxError,
  toArray,
  truthy,
  typeError,
  valueError,
} from './pyvalues.mjs';
import { PyDict } from './pydict.mjs';
import { PySet, buildConstantSetDisplay } from './pyset.mjs';
import { decodeBytesBody, decodeStrBody } from './pytokenizer.mjs';
import { isConstantNode, parseExpression } from './pyparser.mjs';
import { binaryOp, compareOp, installFormatters, unaryOp } from './pyops.mjs';
import { applyFormatSpec, getAttribute, getItem, makeBuiltins } from './pybuiltins.mjs';
import { pyRepr, pyStr } from './pyrepr.mjs';

installFormatters(pyStr, pyRepr);

class Scope {
  constructor(parent) {
    this.vars = new Map();
    this.parent = parent;
  }

  lookup(name) {
    let s = this;
    while (s !== null) {
      if (s.vars.has(name)) return s.vars.get(name);
      s = s.parent;
    }
    return undefined;
  }

  define(name, value) {
    this.vars.set(name, value);
  }
}

export class Evaluator {
  constructor() {
    this.builtins = makeBuiltins((fn, args, kwargs = []) => this.callValue(fn, args, kwargs));
    this.global = new Scope(null);
  }

  run(source) {
    return this.eval(parseExpression(source), this.global);
  }

  // -------------------------------------------------------------------------

  eval(node, scope) {
    switch (node.kind) {
      case 'Num':
        return this.evalNum(node);
      case 'Str':
        return this.evalStr(node, scope);
      case 'Const':
        if (node.name === 'None') return NONE;
        if (node.name === 'True') return mkBool(true);
        if (node.name === 'False') return mkBool(false);
        return NONE; // Ellipsis is never observable here
      case 'Name': {
        const local = scope.lookup(node.id);
        if (local !== undefined) return local;
        const builtin = this.builtins.get(node.id);
        if (builtin !== undefined) return builtin;
        throw nameError(`name '${node.id}' is not defined`);
      }
      case 'Paren':
        return this.eval(node.value, scope);
      case 'Tuple':
        return mkTuple(this.evalElements(node.elts, scope));
      case 'List':
        return mkList(this.evalElements(node.elts, scope));
      case 'Set': {
        const values = this.evalElements(node.elts, scope);
        // All-constant set displays go through a folded frozenset in CPython,
        // which changes iteration order — reproduce that path exactly.
        if (node.elts.every(isConstantNode)) return buildConstantSetDisplay(values, T_SET);
        return PySet.of(values, T_SET);
      }
      case 'Dict':
        return this.evalDict(node, scope);
      case 'ListComp':
        return mkList(this.runComprehension(node, scope, (out, v) => out.push(v)));
      case 'SetComp': {
        const s = new PySet(T_SET);
        this.runComprehension(node, scope, (_out, v) => s.add(v));
        return s;
      }
      case 'DictComp': {
        const d = new PyDict();
        this.runComprehensionPairs(node, scope, (k, v) => d.set(k, v));
        return d;
      }
      case 'GenExp': {
        const items = this.runComprehension(node, scope, (out, v) => out.push(v));
        return mkLazy('generator', items[Symbol.iterator]());
      }
      case 'UnaryOp':
        return unaryOp(node.op, this.eval(node.operand, scope));
      case 'BinOp':
        return binaryOp(node.op, this.eval(node.left, scope), this.eval(node.right, scope));
      case 'BoolOp': {
        let last = NONE;
        for (const child of node.values) {
          last = this.eval(child, scope);
          const t = truthy(last);
          if (node.op === 'and' && !t) return last;
          if (node.op === 'or' && t) return last;
        }
        return last;
      }
      case 'Compare': {
        let left = this.eval(node.left, scope);
        for (let i = 0; i < node.ops.length; i += 1) {
          const right = this.eval(node.comparators[i], scope);
          const result = compareOp(node.ops[i], left, right);
          if (!truthy(result)) return mkBool(false);
          left = right;
        }
        return mkBool(true);
      }
      case 'IfExp':
        return truthy(this.eval(node.test, scope))
          ? this.eval(node.body, scope)
          : this.eval(node.orelse, scope);
      case 'Lambda':
        return { t: 'function', name: '<lambda>', node, scope };
      case 'Call':
        return this.evalCall(node, scope);
      case 'Attribute':
        return getAttribute(this.eval(node.value, scope), node.attr, (fn, args, kwargs = []) =>
          this.callValue(fn, args, kwargs),
        );
      case 'Subscript': {
        const target = this.eval(node.value, scope);
        const key = this.evalSubscriptKey(node.slice, scope);
        return getItem(target, key);
      }
      case 'Starred':
        throw syntaxError("can't use starred expression here");
      default:
        throw syntaxError(`unsupported expression '${node.kind}'`);
    }
  }

  evalNum(node) {
    const { kind, value } = node.num;
    if (kind === 'int') return mkInt(value);
    if (kind === 'float') return mkFloat(value);
    return mkComplex(0, value);
  }

  evalSubscriptKey(slice, scope) {
    if (slice === null) throw syntaxError('invalid subscript');
    if (slice.kind === 'Slice') {
      return mkSlice(
        slice.lower === null ? NONE : this.eval(slice.lower, scope),
        slice.upper === null ? NONE : this.eval(slice.upper, scope),
        slice.step === null ? NONE : this.eval(slice.step, scope),
      );
    }
    return this.eval(slice, scope);
  }

  /** Evaluate display elements, expanding `*iterable` entries. */
  evalElements(elts, scope) {
    const out = [];
    for (const e of elts) {
      if (e.kind === 'Starred') {
        for (const item of iterValues(this.eval(e.value, scope))) out.push(item);
      } else {
        out.push(this.eval(e, scope));
      }
    }
    return out;
  }

  evalDict(node, scope) {
    const d = new PyDict();
    for (let i = 0; i < node.keys.length; i += 1) {
      const keyNode = node.keys[i];
      if (keyNode === null) {
        const src = this.eval(node.values[i], scope);
        if (src.t === T_DICT) for (const [k, v] of src.items()) d.set(k, v);
        else if (typeof src.pyItems === 'function') for (const [k, v] of src.pyItems()) d.set(k, v);
        else throw typeError('argument after ** must be a mapping');
        continue;
      }
      d.set(this.eval(keyNode, scope), this.eval(node.values[i], scope));
    }
    return d;
  }

  // -------------------------------------------------------------------------
  // Strings
  // -------------------------------------------------------------------------

  evalStr(node, scope) {
    const anyBytes = node.pieces.some((p) => p.prefix.includes('b'));
    if (anyBytes) {
      const chunks = node.pieces.map((p) => decodeBytesBody(p.body, p.prefix.includes('r')));
      const total = chunks.reduce((n, c) => n + c.length, 0);
      const out = new Uint8Array(total);
      let at = 0;
      for (const c of chunks) {
        out.set(c, at);
        at += c.length;
      }
      return mkBytes(out);
    }
    let text = '';
    for (const p of node.pieces) {
      if (p.prefix.includes('f')) text += this.evalFString(p.body, p.prefix.includes('r'), scope);
      else text += decodeStrBody(p.body, p.prefix.includes('r'));
    }
    return mkStr(text);
  }

  evalFString(body, raw, scope) {
    let out = '';
    let i = 0;
    while (i < body.length) {
      const c = body[i];
      if (c === '{' && body[i + 1] === '{') {
        out += '{';
        i += 2;
        continue;
      }
      if (c === '}' && body[i + 1] === '}') {
        out += '}';
        i += 2;
        continue;
      }
      if (c === '{') {
        const { expr, conv, spec, next } = scanReplacementField(body, i);
        i = next;
        const value = this.eval(parseExpression(expr), scope);
        out += applyFormatSpec(value, spec, conv);
        continue;
      }
      // Escapes inside the literal part are processed exactly once.
      if (c === '\\' && !raw) {
        const chunk = body.slice(i, i + 12);
        const decoded = decodeStrBody(chunk, false);
        // Re-decode just the escape by measuring how much of the chunk it ate.
        let consumed = 2;
        const e = body[i + 1];
        if (e === 'x') consumed = 4;
        else if (e === 'u') consumed = 6;
        else if (e === 'U') consumed = 10;
        else if (e >= '0' && e <= '7') {
          consumed = 2;
          while (consumed < 4 && body[i + consumed] >= '0' && body[i + consumed] <= '7') consumed += 1;
        }
        out += decodeStrBody(body.slice(i, i + consumed), false);
        void decoded;
        i += consumed;
        continue;
      }
      out += c;
      i += 1;
    }
    return out;
  }

  // -------------------------------------------------------------------------
  // Comprehensions
  // -------------------------------------------------------------------------

  runComprehension(node, scope, emit) {
    const out = [];
    const inner = new Scope(scope);
    this.driveGenerators(node.generators, 0, inner, () => {
      emit(out, this.eval(node.elt, inner));
    });
    return out;
  }

  runComprehensionPairs(node, scope, emit) {
    const inner = new Scope(scope);
    this.driveGenerators(node.generators, 0, inner, () => {
      emit(this.eval(node.key, inner), this.eval(node.value, inner));
    });
  }

  driveGenerators(generators, index, scope, body) {
    if (index === generators.length) {
      body();
      return;
    }
    const gen = generators[index];
    const iterable = this.eval(gen.iter, scope);
    if (!isIterable(iterable)) throw typeError(`'${iterable.t}' object is not iterable`);
    for (const item of iterValues(iterable)) {
      bindTarget(gen.target, item, scope);
      let ok = true;
      for (const cond of gen.ifs) {
        if (!truthy(this.eval(cond, scope))) {
          ok = false;
          break;
        }
      }
      if (ok) this.driveGenerators(generators, index + 1, scope, body);
    }
  }

  // -------------------------------------------------------------------------
  // Calls
  // -------------------------------------------------------------------------

  evalCall(node, scope) {
    const fn = this.eval(node.func, scope);
    const args = [];
    for (const a of node.args) {
      if (a.star) {
        for (const item of iterValues(this.eval(a.node, scope))) args.push(item);
      } else {
        args.push(this.eval(a.node, scope));
      }
    }
    const kwargs = [];
    for (const k of node.keywords) {
      if (k.name === null) {
        const mapping = this.eval(k.node, scope);
        if (mapping.t !== T_DICT) throw typeError('argument after ** must be a mapping');
        for (const [key, value] of mapping.items()) kwargs.push([pyStr(key), value]);
      } else {
        kwargs.push([k.name, this.eval(k.node, scope)]);
      }
    }
    return this.callValue(fn, args, kwargs);
  }

  callValue(fn, args, kwargs = []) {
    if (fn.t === 'function') return this.callLambda(fn, args, kwargs);
    if (typeof fn.fn === 'function') return fn.fn(args, kwargs);
    if (fn.t === T_TYPE) {
      const builtin = this.builtins.get(fn.name);
      if (builtin && typeof builtin.fn === 'function') return builtin.fn(args, kwargs);
    }
    throw typeError(`'${fn.t}' object is not callable`);
  }

  callLambda(fn, args, kwargs) {
    const scope = new Scope(fn.scope);
    const { params, defaults, starArg, kwArg } = fn.node;
    const byName = new Map(kwargs);
    let positional = 0;
    for (let i = 0; i < params.length; i += 1) {
      const name = params[i];
      if (byName.has(name)) {
        scope.define(name, byName.get(name));
        byName.delete(name);
      } else if (positional < args.length) {
        scope.define(name, args[positional]);
        positional += 1;
      } else if (defaults[i] !== null) {
        scope.define(name, this.eval(defaults[i], fn.scope));
      } else {
        throw typeError(`<lambda>() missing required argument: '${name}'`);
      }
    }
    if (starArg !== null) scope.define(starArg, mkTuple(args.slice(positional)));
    if (kwArg !== null) {
      const d = new PyDict();
      for (const [k, v] of byName) d.set(mkStr(k), v);
      scope.define(kwArg, d);
    }
    return this.eval(fn.node.body, scope);
  }
}

function bindTarget(target, value, scope) {
  if (target.kind === 'TargetName') {
    scope.define(target.id, value);
    return;
  }
  if (target.kind === 'TargetStar') {
    bindTarget(target.value, value, scope);
    return;
  }
  const items = toArray(value);
  const elts = target.elts;
  const starIndex = elts.findIndex((e) => e.kind === 'TargetStar');
  if (starIndex === -1) {
    if (items.length !== elts.length) {
      throw valueError(
        items.length < elts.length
          ? `not enough values to unpack (expected ${elts.length}, got ${items.length})`
          : `too many values to unpack (expected ${elts.length})`,
      );
    }
    elts.forEach((e, i) => bindTarget(e, items[i], scope));
    return;
  }
  const before = elts.slice(0, starIndex);
  const after = elts.slice(starIndex + 1);
  before.forEach((e, i) => bindTarget(e, items[i], scope));
  const rest = items.slice(before.length, items.length - after.length);
  bindTarget(elts[starIndex].value, mkList(rest), scope);
  after.forEach((e, i) => bindTarget(e, items[items.length - after.length + i], scope));
