      bangAt = i;
      continue;
    }
    if (depth === 1 && c === ':' && colonAt === -1) {
      colonAt = i;
      continue;
    }
  }
  if (exprEnd === -1) throw syntaxError("f-string: expecting '}'");

  const cut = bangAt !== -1 ? bangAt : colonAt !== -1 ? colonAt : exprEnd;
  const expr = body.slice(start + 1, cut);
  if (bangAt !== -1) conv = body.slice(bangAt + 1, colonAt !== -1 ? colonAt : exprEnd);
  if (colonAt !== -1) spec = body.slice(colonAt + 1, exprEnd);
  return { expr, conv, spec, next: exprEnd + 1 };
}

