/**
 * boltons/iterutils.mjs
 *
 * Behavioural re-implementations of the four `boltons.iterutils` helpers the
 * source program uses.  Everything here works on Python values (see
 * ../pyvalues.mjs) so that ordering and type semantics survive.
 */

import {
  T_BOOL,
  isIterable,
  isStringish,
  iterValues,
  mkBool,
  mkList,
  mkTuple,
  valueError,
  typeError,
} from '../pyvalues.mjs';
import { PyDict } from '../pydict.mjs';

/**
 * `flatten(iterable)` — recursively expand every nested iterable.
 *
 * boltons guards with `isinstance(item, Iterable) and not isinstance(item,
 * (str, bytes))`, so strings and bytes stay atomic while dicts collapse to
 * their *keys* (iterating a mapping yields keys) and empty containers vanish.
 *
 * @returns {object[]} a flat JS array of Python values
 */
export function flatten(iterable) {
  if (!isIterable(iterable)) {
    throw typeError(`flatten() expected an iterable, not ${iterable.t}`);
  }
  const out = [];
  const walk = (value) => {
    for (const item of iterValues(value)) {
      if (isIterable(item) && !isStringish(item)) walk(item);
      else out.push(item);
    }
  };
  walk(iterable);
  return out;
}

/**
 * `chunked(src, size)` — split into consecutive runs of `size`.  With no
 * `fill` argument the final chunk is simply shorter.
 *
 * @param {object[]} items
 * @param {number} size
 * @returns {object[][]}
 */
export function chunked(items, size) {
  if (size <= 0) throw valueError('expected size > 0');
  const out = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}

/**
 * `bucketize(src, key)` — group values by `key(value)`.
 *
 * Returns a real Python dict so that insertion order and Python key equality
 * (`1 == 1.0 == True`) govern the printed result.
 *
 * @param {object[]} items
 * @param {(value: object) => object} keyFn - returns a Python value
 */
export function bucketize(items, keyFn) {
  const ret = new PyDict();
  for (const value of items) {
    const k = keyFn(value);
    const bucket = ret.setdefault(k, mkList([]));
    bucket.v.push(value);
  }
  return ret;
}

/**
 * `partition(src, key)` — boltons implements this as
 * `bucketize(...)` followed by `.get(True, []), .get(False, [])`, so the
 * result is a 2-tuple of lists in that order.
 *
 * @param {object[]} items
 * @param {(value: object) => object} keyFn - must return a Python bool
 */
