/**
 * `flatten(iterable)` — recursively expand every nested iterable.
 *
 * boltons guards with `isinstance(item, Iterable) and not isinstance(item,
 * (str, bytes))`, so strings and bytes stay atomic while dicts collapse to
 * their *keys* (iterating a mapping yields keys) and empty containers vanish.
 *
 * @returns {object[]} a flat JS array of Python values
 */
export function flatten(iterable) {
  if (!isIterable(iterable)) {
    throw typeError(`flatten() expected an iterable, not ${iterable.t}`);
  }
  const out = [];
  const walk = (value) => {
    for (const item of iterValues(value)) {
      if (isIterable(item) && !isStringish(item)) walk(item);
      else out.push(item);
    }
