 *  - `dict(omd)` does *not* copy the internal storage.  `OMD` overrides
 *    `__iter__`, so CPython's `dict()` fast path is skipped and the slow path
 *    (`keys()` + `__getitem__`) runs instead — giving `{unique key: last
 *    value}` in first-insertion order.
 */

import { T_DICT, keyError, mkList, mkTuple, mkStr } from '../pyvalues.mjs';
import { PyDict } from '../pydict.mjs';
import { hashKey } from '../pyhash.mjs';
import { dictRepr, pyRepr } from '../pyrepr.mjs';

export class OrderedMultiDict {
  constructor(pairs) {
    this.t = 'OrderedMultiDict';
    /** Every (key, value) pair, in insertion order. */
    this._pairs = [];
    /** hashKey -> {k, values[]}, iterated in first-insertion order. */
    this._groups = new Map();
    if (pairs) for (const [k, v] of pairs) this.add(k, v);
  }

  get size() {
    return this._groups.size;
  }

  add(k, v) {
    const key = hashKey(k);
    let group = this._groups.get(key);
    if (group === undefined) {
      group = { k, values: [] };
      this._groups.set(key, group);
    }
    group.values.push(v);
    this._pairs.push([k, v]);
  }

  /** `__setitem__` semantics: replace every value for `k` with a single one. */
  set(k, v) {
    const key = hashKey(k);
    const group = this._groups.get(key);
    if (group === undefined) {
      this.add(k, v);
      return;
    }
    group.values = [v];
    this._pairs = this._pairs.filter(([existing]) => hashKey(existing) !== key);
    this._pairs.push([k, v]);
