/**
 * argparse.mjs
 *
 * A focused re-implementation of the slice of `argparse` this program needs,
 * reproducing CPython 3.10+ formatting exactly:
 *
 *   usage: PROG [-h] --a A
 *
 *   options:
 *     -h, --help  show this help message and exit
 *     --a A       Nested dictionary structure
 *
 * The two-space gutter, the 10-column invocation field and the `options:`
 * heading all come from `HelpFormatter`'s arithmetic:
 * `help_position = min(max_invocation_len + indent + 2, 24)`.
 */

const HELP_INDENT = 2;
const MAX_HELP_POSITION = 24;

class Action {
  constructor({ optionStrings, dest, required, help, metavar, isHelp }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.required = Boolean(required);
    this.help = help ?? '';
    this.metavar = metavar;
    this.isHelp = Boolean(isHelp);
  }

  /** `--a A` for value-taking options, `-h, --help` for flags. */
  get invocation() {
    if (this.isHelp) return this.optionStrings.join(', ');
    const arg = this.metavar ?? this.dest.toUpperCase();
    return this.optionStrings.map((o) => `${o} ${arg}`).join(', ');
  }

  /** How the option appears inside the usage line. */
  get usageFragment() {
    const first = this.optionStrings[0];
    const body = this.isHelp ? first : `${first} ${this.metavar ?? this.dest.toUpperCase()}`;
    return this.required ? body : `[${body}]`;
  }
}

export class ArgumentParser {
  constructor({ prog, addHelp = true } = {}) {
    this.prog = prog;
    this.actions = [];
    if (addHelp) {
      this.actions.push(
        new Action({
          optionStrings: ['-h', '--help'],
          dest: 'help',
          help: 'show this help message and exit',
          isHelp: true,
        }),
      );
    }
  }

  /**
   * `add_argument('--a', type=str, required=True, help='...')`
   * Only long/short option strings are supported — this program has no
   * positionals.
   */
  addArgument(name, options = {}) {
    const dest = name.replace(/^--?/, '').replace(/-/g, '_');
    this.actions.push(
      new Action({
        optionStrings: [name],
        dest,
        required: options.required,
        help: options.help,
        metavar: options.metavar,
      }),
    );
  }

  get valueActions() {
    return this.actions.filter((a) => !a.isHelp);
  }

  formatUsage() {
    const parts = this.actions.map((a) => a.usageFragment);
    return `usage: ${this.prog}${parts.length ? ' ' + parts.join(' ') : ''}\n`;
  }

  formatHelp() {
    const invocations = this.actions.map((a) => a.invocation);
    const maxLength = Math.max(0, ...invocations.map((s) => s.length + HELP_INDENT));
    const helpPosition = Math.min(maxLength + 2, MAX_HELP_POSITION);
    const actionWidth = helpPosition - HELP_INDENT - 2;

    let out = this.formatUsage();
    out += '\noptions:\n';
    for (const action of this.actions) {
      const header = action.invocation;
      if (header.length <= actionWidth) {
        out += ' '.repeat(HELP_INDENT) + header.padEnd(actionWidth) + '  ' + action.help + '\n';
      } else {
        out += ' '.repeat(HELP_INDENT) + header + '\n';
        out += ' '.repeat(helpPosition) + action.help + '\n';
      }
    }
    return out;
  }

  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  printHelp() {
    process.stdout.write(this.formatHelp());
    process.exit(0);
  }

  /** Resolve `--abc` allowing unambiguous abbreviations, as argparse does. */
  findLongOption(token) {
    const exact = this.actions.find((a) => a.optionStrings.includes(token));
    if (exact) return exact;
    const candidates = [];
    for (const action of this.actions) {
      for (const opt of action.optionStrings) {
        if (opt.startsWith('--') && opt.startsWith(token)) candidates.push(action);
      }
    }
    const unique = Array.from(new Set(candidates));
    if (unique.length === 1) return unique[0];
    if (unique.length > 1) {
      this.error(
        `ambiguous option: ${token} could match ${unique
          .flatMap((a) => a.optionStrings.filter((o) => o.startsWith('--')))
          .join(', ')}`,
      );
    }
    return null;
  }

  parseArgs(argv) {
    const values = Object.create(null);
    for (const action of this.valueActions) values[action.dest] = undefined;

    const extras = [];
    const seen = new Set();
    let i = 0;
    let onlyPositional = false;

    const looksLikeOption = (token) =>
      typeof token === 'string' && token.length > 1 && token.startsWith('-') && token !== '-';

    while (i < argv.length) {
      const token = argv[i];

      if (onlyPositional) {
        extras.push(token);
        i += 1;
        continue;
      }
      if (token === '--') {
        onlyPositional = true;
        i += 1;
        continue;
      }

      if (token.startsWith('--')) {
        const eq = token.indexOf('=');
        const name = eq === -1 ? token : token.slice(0, eq);
        const inline = eq === -1 ? null : token.slice(eq + 1);
        const action = this.findLongOption(name);
        if (action === null) {
          extras.push(token);
          i += 1;
          continue;
        }
        if (action.isHelp) {
          this.printHelp();
        }
        seen.add(action.dest);
        if (inline !== null) {
          values[action.dest] = inline;
          i += 1;
          continue;
        }
        const next = argv[i + 1];
        if (next === undefined || looksLikeOption(next)) {
          this.error(`argument ${name}: expected one argument`);
        }
        values[action.dest] = next;
        i += 2;
        continue;
      }

      if (looksLikeOption(token)) {
        const action = this.actions.find((a) => a.optionStrings.includes(token));
        if (action === undefined) {
          extras.push(token);
          i += 1;
          continue;
        }
        if (action.isHelp) this.printHelp();
        seen.add(action.dest);
        const next = argv[i + 1];
        if (next === undefined || looksLikeOption(next)) {
          this.error(`argument ${token}: expected one argument`);
        }
        values[action.dest] = next;
        i += 2;
        continue;
      }

      extras.push(token);
      i += 1;
    }

    // argparse raises the "required" error from inside parse_known_args, so it
    // wins over "unrecognized arguments".
    const missing = this.valueActions
      .filter((a) => a.required && !seen.has(a.dest))
      .map((a) => a.optionStrings[0]);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return values;
  }
}

