        const name = eq === -1 ? token : token.slice(0, eq);
        const inline = eq === -1 ? null : token.slice(eq + 1);
        const action = this.findLongOption(name);
        if (action === null) {
          extras.push(token);
          i += 1;
          continue;
        }
        if (action.isHelp) {
          this.printHelp();
        }
        seen.add(action.dest);
        if (inline !== null) {
          values[action.dest] = inline;
          i += 1;
          continue;
        }
        const next = argv[i + 1];
        if (next === undefined || looksLikeOption(next)) {
          this.error(`argument ${name}: expected one argument`);
        }
        values[action.dest] = next;
        i += 2;
        continue;
      }

      if (looksLikeOption(token)) {
        const action = this.actions.find((a) => a.optionStrings.includes(token));
        if (action === undefined) {
          extras.push(token);
          i += 1;
          continue;
        }
        if (action.isHelp) this.printHelp();
        seen.add(action.dest);
        const next = argv[i + 1];
        if (next === undefined || looksLikeOption(next)) {
          this.error(`argument ${token}: expected one argument`);
        }
        values[action.dest] = next;
        i += 2;
        continue;
      }

      extras.push(token);
      i += 1;
    }

    // argparse raises the "required" error from inside parse_known_args, so it
    // wins over "unrecognized arguments".
    const missing = this.valueActions
      .filter((a) => a.required && !seen.has(a.dest))
      .map((a) => a.optionStrings[0]);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

