/**
 * lib/runtime.mjs
 *
 * Small process-level helpers: `print`, and an approximation of CPython's
 * uncaught-exception behaviour (traceback on stderr, exit status 1).
 */

import { PyError } from './pyvalues.mjs';
import { pyStr } from './pyrepr.mjs';

/** `print(value)` — one value, `str()`-formatted, newline-terminated. */
export function print(value) {
  process.stdout.write(pyStr(value) + '\n');
}

/**
 * Mirror an uncaught Python exception: traceback to stderr, exit code 1.
 *
 * The reference build is a PyInstaller bundle, so its trailing
 * `[PYI-<pid>:ERROR] ...` line embeds the process id and can never be
 * reproduced byte for byte; we emit the traceback and the exception line,
 * which is the part that carries information.
 */
export function abortWithTraceback(err, frames) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of frames) {
    lines.push(`  File "test19.py", line ${frame.line}, in <module>`);
    lines.push(`    ${frame.source}`);
  }
  if (err instanceof PyError) {
    lines.push(err.pyMessage === '' ? err.kind : `${err.kind}: ${err.pyMessage}`);
  } else {
    lines.push(`RuntimeError: ${err.message}`);
  }
  process.stderr.write(lines.join('\n') + '\n');
  process.exit(1);
}

