#!/usr/bin/env node
/**
 * test19.mjs
 *
 * Node.js (ESM) port of /workspace/dataset/test19.py.
 *
 * The Python original evaluates its `--a` argument with `eval()` and then runs
 * it through four groups of `boltons` calls, printing each intermediate result.
 * Every construct is reproduced through the local library in ./lib:
 *
 *   lib/pyeval.mjs           the `eval()` sandbox (parser + evaluator)
 *   lib/pyrepr.mjs           `repr()` / `str()`, so `print` matches byte for byte
 *   lib/boltons/iterutils    flatten / chunked / partition / bucketize
 *   lib/boltons/dictutils    OrderedMultiDict (OMD) / FrozenDict
 *   lib/argparse.mjs         the CLI surface
 */

import { ArgumentParser } from './lib/argparse.mjs';
import { PyDict } from './lib/pydict.mjs';
import { PyError, isIntLike, isIntOrFloat, mkBool, mkInt, mkList, mkStr, strChars } from './lib/pyvalues.mjs';
import { getAttribute } from './lib/pybuiltins.mjs';
import { compareOp, binaryOp } from './lib/pyops.mjs';
import { pyStr } from './lib/pyrepr.mjs';
import { Evaluator } from './lib/pyeval.mjs';
import { bucketize, chunked, flatten, partition } from './lib/boltons/iterutils.mjs';
import { FrozenDict, OMD } from './lib/boltons/dictutils.mjs';
import { abortWithTraceback, print } from './lib/runtime.mjs';

// ---------------------------------------------------------------------------
// Command line: argparse.ArgumentParser(); --a, type=str, required=True
// ---------------------------------------------------------------------------

// `prog` is pinned to the reference build's name so that the usage, help and
// error text this port emits is identical to
// `/workspace/dataset/test19_executable`, which derives it from argv[0].
const parser = new ArgumentParser({ prog: 'test19_executable' });
parser.addArgument('--a', {
  type: String,
  required: true,
  help: 'Nested dictionary structure',
});
const args = parser.parseArgs(process.argv.slice(2));

// ---------------------------------------------------------------------------
// nested_dict = eval(args.a)
// ---------------------------------------------------------------------------

const evaluator = new Evaluator();
const callable = (fn, callArgs = []) => evaluator.callValue(fn, callArgs, []);

let nestedDict;
try {
  nestedDict = evaluator.run(args.a);
} catch (err) {
  if (err instanceof PyError) {
    abortWithTraceback(err, [{ line: 9, source: 'nested_dict = eval(args.a)' }]);
  }
  throw err;
}

/** `nested_dict.keys()` etc. — routed through attribute lookup so that a
 *  non-mapping argument raises the same AttributeError Python would. */
function viewOf(name, line, source) {
  try {
    return callable(getAttribute(nestedDict, name, callable));
  } catch (err) {
    if (err instanceof PyError) abortWithTraceback(err, [{ line, source }]);
    throw err;
  }
}

const keysView = viewOf('keys', 12, 'result1 = list(flatten(nested_dict.keys()))  # 展平键');
const valuesView = viewOf('values', 14, 'result2 = list(flatten(nested_dict.values()))  # 展平值');
const itemsView = viewOf('items', 16, 'result3 = list(flatten(nested_dict.items()))  # 展平键值对');

// ---------------------------------------------------------------------------
// Group 1: flattening
// ---------------------------------------------------------------------------

const result1 = flatten(keysView);
print(mkList(result1));

const result2 = flatten(valuesView);
print(mkList(result2));

const result3 = flatten(itemsView);
print(mkList(result3));

const result4 = flatten(mkList([keysView, valuesView]));
print(mkList(result4));

// ---------------------------------------------------------------------------
// Group 2: chunking
// ---------------------------------------------------------------------------

const asChunks = (chunks) => mkList(chunks.map((chunk) => mkList(chunk)));

const result5 = chunked(result2, 2);
print(asChunks(result5));

const result6 = chunked(result2, 3);
print(asChunks(result6));

const result7 = chunked(result1, 2);
print(asChunks(result7));

const result8 = chunked(result1, 3);
print(asChunks(result8));

// ---------------------------------------------------------------------------
// Group 3: partitioning and grouping
// ---------------------------------------------------------------------------

const ZERO = mkInt(0n);
const ONE = mkInt(1n);
const TWO = mkInt(2n);

/** `len(str(x))` — Python counts codepoints, not UTF-16 units. */
const strLen = (value) => BigInt(strChars(pyStr(value)).length);

let result9;
let result10;

// `all(isinstance(x, (int, float)) for x in result2)` — bool passes as int, and
// an empty result2 makes all() true, selecting this branch.
if (result2.every(isIntOrFloat)) {
  result9 = partition(result2, (x) => compareOp('>', x, ZERO));
  print(result9);
  result10 = bucketize(result2, (x) => (isIntLike(x) ? binaryOp('%', x, TWO) : ZERO));
  print(result10);
} else {
  result9 = partition(result2, (x) => compareOp('>', mkInt(strLen(x)), ONE));
  print(result9);
  result10 = bucketize(result2, (x) => mkInt(strLen(x)));
  print(result10);
}

const result11 = partition(result2, (x) => mkBool(isIntLike(x)));
print(result11);

const result12 = bucketize(result2, (x) => mkStr(x.t));
print(result12);

// ---------------------------------------------------------------------------
// Group 4: dictionary operations
// ---------------------------------------------------------------------------

const omd1 = new OMD();
print(omd1);

const omd2 = new OMD();
print(omd2);

result2.slice(0, 5).forEach((item, i) => {
  omd1.add(mkStr(`key_${i % 3}`), item);
  omd2.add(mkStr(`item_${i % 2}`), item);
});

const result13 = omd1.keys();
print(mkList(result13));

const result14 = omd2.keys();
print(mkList(result14));

// `dict(omd)` uses keys() + __getitem__, i.e. unique key -> most recent value.
const result15 = new FrozenDict(PyDict.of(omd1.pyItems()));
print(result15);

// ---------------------------------------------------------------------------
// Group 5: final processing
// ---------------------------------------------------------------------------

const result16 = new FrozenDict(PyDict.of(omd2.pyItems()));
print(result16);

const result17 = new FrozenDict(
  PyDict.of(result15.items().map(([k, v]) => [k, mkInt(strLen(v))])),
);
print(result17);

